    } catch(error) { if(token===S.planToken) {S.plan={error:error.message}; if(S.view==='overview')renderAfterModal();} }
  }
  function renderAfterModal() {
    if (root.querySelector('#es-modal')?.open) deferredRender = true;
    else render();
