/* Each area owns its scrolling. No body/global page rules are needed. */
:host{--radius:18px;--sheen:rgba(255,255,255,.06);--glass-line:rgba(255,255,255,.10);--material:rgba(153,125,210,.055);--surface-shadow:0 12px 35px rgba(0,0,0,.12);}
