:host([data-theme="peach"]){--sheen:rgba(255,255,255,.85);--glass-line:rgba(255,255,255,.9);--material:rgba(177,111,56,.05);--surface-shadow:0 12px 30px rgba(128,65,34,.075);--radius:21px;}
*{box-sizing:border-box}button,input,select,textarea{font:inherit;color:inherit;letter-spacing:normal;text-transform:none;line-height:1.4;min-height:0;max-width:100%;}button{appearance:none;border:0;background:transparent;cursor:pointer;padding:0;margin:0;text-align:left;white-space:normal;border-radius:0;min-width:0;}button:disabled{opacity:.32;cursor:default;pointer-events:none;}input,select{border:1px solid var(--line);border-radius:9px;background:var(--panel);padding:10px 12px;outline:0;}input:focus,select:focus{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft);}select{color-scheme:var(--scheme);cursor:pointer;}input[type="checkbox"]{accent-color:var(--accent);width:17px;height:17px;flex:0 0 17px;}input[type="date"]{color-scheme:var(--scheme);}button:focus-visible,a:focus-visible,[tabindex]:focus-visible{outline:2px solid var(--accent);outline-offset:3px;}button:focus:not(:focus-visible){outline:0;}p,h1,h2,h3{margin:0}strong,b{font-weight:650}svg{display:block;flex-shrink:0}button svg{pointer-events:none;}small{font-size:12px}.icon{flex-shrink:0;}::selection{background:var(--accent);color:var(--on-accent);}::-webkit-scrollbar{width:7px;height:7px}::-webkit-scrollbar-track{background:transparent}::-webkit-scrollbar-thumb{background:var(--line);border:1px solid var(--side);border-radius:9px}
.app{font-family:Inter,"Segoe UI",-apple-system,BlinkMacSystemFont,Arial,sans-serif;font-size:14px;line-height:1.5;font-weight:400;text-align:left;color:var(--text);direction:ltr;letter-spacing:normal;white-space:normal;text-transform:none;height:100%;position:relative;isolation:isolate;color-scheme:var(--scheme);}
.frame{height:100%;min-height:0}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);height:100%;width:100%;overflow:hidden;min-width:0;min-height:0;background:var(--bg);}
.sidebar{height:100%;min-height:0;min-width:0;display:flex;flex-direction:column;padding:30px 16px 16px;background:linear-gradient(160deg,var(--side),var(--bg));border-right:1px solid var(--line-soft);position:relative;overflow:hidden;}
