/* Shared-home controls. No selectors escape this shadow root. */
.build-label{display:inline-flex;font:11px/1.3 ui-monospace,monospace;letter-spacing:.08em;color:var(--accent);border:1px solid var(--line);padding:5px 8px;border-radius:6px}
.home-editor-intro p{color:var(--muted);line-height:1.7;margin:12px 0 22px}
.home-widget-list{display:flex;flex-direction:column;gap:10px;margin:18px 0}
.home-widget-row{border:1px solid var(--line);border-radius:13px;background:var(--panel);padding:16px;display:flex;align-items:center;gap:16px;justify-content:space-between;min-width:0}
