.home-widget-tools{display:flex;align-items:center;gap:8px;flex-shrink:0}.home-widget-tools label{display:flex;flex-direction:column;gap:5px;font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.home-widget-tools select{font-size:12px;max-width:145px;min-height:34px}
.widget-order{display:flex;flex-direction:column;gap:0}.widget-order .icon-button{width:28px;height:28px}.home-editor-actions{display:flex;gap:8px;flex-wrap:wrap;padding-top:10px}.context-tip{font-size:11px;line-height:1.6;color:var(--muted);margin:8px 12px;max-width:240px}
