/* Shared-home links wrap in the smallest organizer window; never widen the page. */
.help-strip>div{display:flex;flex-wrap:wrap;align-items:center;gap:4px;min-width:0;max-width:100%;}
/* Menus use viewport coordinates in BOTH the full workspace and shared home. */
.context-menu{position:fixed;}

/* The complete workspace exists before its asynchronous collection snapshot. */
.workspace-loading{min-height:100vh;box-sizing:border-box;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;padding:40px;background:var(--bg);color:var(--text);text-align:center;}
.workspace-loading h1{font-size:24px;letter-spacing:-.6px;margin:0;}
.workspace-loading p{font-size:14px;line-height:1.7;color:var(--muted);max-width:510px;}
.workspace-loading>div:last-child{display:flex;flex-wrap:wrap;justify-content:center;gap:12px;}
.loading-mark svg{width:42px;height:42px;color:var(--accent);}
.tree-pin{flex:0 0 28px;opacity:.65;}
.tree-row:hover .tree-pin,.tree-pin:focus-visible{opacity:1;}

/* A direct route to the real planner; never a duplicated Exam Sprout app. */
.sprout-open{white-space:nowrap;font-size:12px;flex-shrink:0}
@media(max-width:1120px){.sprout-open{padding:9px}.sprout-open svg{display:none}.search{max-width:250px}}
