:host([data-theme="linen"]){--studio-light:linear-gradient(120deg,#92744516,transparent 60%);--studio-pattern:repeating-linear-gradient(0deg,transparent 0 3px,#756a4005 4px 5px);--studio-radius:12px;--studio-font:Georgia,"Times New Roman",serif;}
:host([data-theme="matcha"]){--studio-light:radial-gradient(ellipse at 100% 0%,#7f9e4240,transparent 68%);--studio-pattern:linear-gradient(135deg,transparent 40%,#d8ce8538 85%,transparent);--studio-radius:28px;--studio-font:Georgia,"Times New Roman",serif;}
