    function suitePlans(){
      const data=state.suite||{},plans=(data.plans||[]).filter(x=>!x.archived);
      return `<section class="suite-exams" aria-label="Saved exam plans"><div class="suite-exams-head"><div><h2 class="suite-section-title">Exam Studio</h2><p>One planner. Your existing exams, practice and progress.</p></div>${btn('suite-open','New exam','plus','secondary','data-view="new"')}</div>${data.warning?`<p role="status" class="suite-warning">${esc(data.warning)}</p>`:''}${data.draft?`<div class="suite-draft"><span>Saved unfinished session · resume through the practice page</span>${btn('suite-open','Open practice','arrow','quiet','data-view="practice"')}</div>`:''}${plans.length?`<div class="suite-plan-list">${plans.slice(0,6).map((e,i)=>`<article class="suite-plan"><div class="suite-plan-top"><span class="suite-plan-index">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(e.name)}</h3><small>${e.due?esc(new Date(e.due).toLocaleDateString(undefined,{month:'short',day:'numeric'}))+' · ':''}${e.deck_ids?.length||0} selected ${(e.deck_ids?.length||0)===1?'folder':'folders'}${e.filtered?' · Search-filtered':''}</small></div></div><div class="suite-plan-actions">${btn('suite-open','Plan','calendar','',`data-view="overview" data-id="${esc(e.id)}"`)}${btn('suite-open','Practice','book','',`data-view="practice" data-id="${esc(e.id)}"`)}${btn('suite-open','Pip Study','focus','',`data-view="pip" data-id="${esc(e.id)}"`)}${!e.filtered?btn('suite-focus','Focus folders','layers','',`data-id="${esc(e.id)}" title="Pin these folders for normal Anki review; does not create another exam plan"`):''}</div></article>`).join('')}</div>${plans.length>6?btn('suite-open',`All ${plans.length} exam plans`,'arrow','quiet','data-view="overview"'):''}`:`<div class="suite-hub-empty"><div><strong>Plan it once. Prepare in one place.</strong><p>Create an exam, choose its decks and emphasis, then build a mock or a targeted practice session. Your existing focus folders stay available below.</p></div>${btn('suite-open','Create first exam','plus','primary','data-view="new"')}</div>`}</section>`;
