    function authoringHub(){const a=state.authoring;return a?.available?`<section class="authoring-hub" aria-label="Card Studio workspace"><div><span class="eyebrow">FROM MATERIAL TO MEMORY</span><h2>Shape your next useful card.</h2><p>Keep the source. Refine the question. Add only what you approve.</p></div><div class="authoring-hub-actions">${btn('authoring-open','Create cards','plus','primary','data-view="studio"')}${btn('authoring-open',`${fmt(a.projects)} source projects`,'book','secondary','data-view="library"')}${btn('authoring-open',`${fmt(a.drafts)} drafts`,'edit','quiet','data-view="drafts"')}${btn('authoring-open',`${fmt(a.repairs)} need attention`,'shield','quiet','data-view="improve"')}</div></section>`:'';}
    function workflowInbox(){
