web/card-studio-shell.css:
/* Suite Card Studio. Scoped to this document and its own root, never card content or mask coordinates. */
html[data-atelier-card-studio="true"],html[data-atelier-card-studio="true"] body{margin:0;height:100%;overflow:hidden;}
#workshop[data-integrated="true"]{--page-pad:clamp(20px,3vw,46px);font-family:"Segoe UI",system-ui,sans-serif;}
#workshop[data-integrated="true"] .app-shell{grid-template-columns:230px minmax(0,1fr);}
#workshop[data-integrated="true"] .topbar{height:auto;min-height:0;display:grid;grid-template-columns:minmax(120px,1fr) auto;grid-template-areas:"crumb suite" "search search";gap:10px 20px;padding:16px var(--page-pad);flex:0 0 auto;background:var(--sidebar);}
#workshop[data-integrated="true"] .breadcrumb{grid-area:crumb;min-width:0;flex-wrap:wrap;row-gap:4px;font-size:13px;}
#workshop[data-integrated="true"] .breadcrumb strong{max-width:min(35vw,420px);}
#workshop[data-integrated="true"] .suite-header-actions{grid-area:suite;display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end;}
#workshop[data-integrated="true"] .suite-world{display:flex;align-items:center;gap:8px;margin:0;font-size:11px;color:var(--muted);}
#workshop[data-integrated="true"] .suite-world select{width:150px;min-height:38px;color:var(--fg);background:var(--panel);border:1px solid var(--line);border-radius:10px;font:13px "Segoe UI",system-ui,sans-serif;padding:8px;}
#workshop[data-integrated="true"] .suite-world[hidden]{display:none;}
#workshop[data-integrated="true"] .top-actions{grid-area:search;display:flex;flex-wrap:nowrap;min-width:0;}
#workshop[data-integrated="true"] .command-trigger{width:auto;flex:1;min-width:0;max-width:640px;min-height:38px;background:var(--panel);}
#workshop[data-integrated="true"] .top-actions .icon-btn{flex:0 0 36px;}
#workshop[data-integrated="true"] .sidebar{padding:28px 15px 18px;gap:25px;}
#workshop[data-integrated="true"] .brand strong{font:750 29px/1 "Segoe UI",system-ui,sans-serif;letter-spacing:-1.5px;}
#workshop[data-integrated="true"] .brand small{font:600 9px/1.4 "Segoe UI",system-ui,sans-serif;letter-spacing:1.6px;}
#workshop[data-integrated="true"] .nav-link{min-height:42px;font-size:13px;border-radius:12px;}
#workshop[data-integrated="true"] .page{max-width:1550px;padding-block:30px 40px;}
#workshop[data-suite-theme="true"] .page-heading h1,#workshop[data-suite-theme="true"] .project-hero h1{font-family:var(--world-heading,Georgia,serif);font-size:clamp(30px,3.5vw,46px);line-height:1.15;letter-spacing:-1px;}
#workshop[data-suite-theme="true"] .page-heading p{font-size:14px;line-height:1.65;max-width:700px;}
#workshop[data-suite-theme="true"] .summary-strip{background:linear-gradient(130deg,var(--panel),var(--raised));border-radius:var(--world-radius,18px);padding-block:18px;}
#workshop[data-integrated="true"] .summary-number strong{font:650 29px/1.3 "Segoe UI",system-ui,sans-serif;font-variant-numeric:tabular-nums;}
#workshop[data-suite-theme="true"] .studio-panel,#workshop[data-suite-theme="true"] .panel,#workshop[data-suite-theme="true"] .library-note,#workshop[data-suite-theme="true"] .settings-section{border-radius:var(--world-radius,18px);border-color:var(--line);}
#workshop[data-integrated="true"] button{font-family:"Segoe UI",system-ui,sans-serif;}
#workshop[data-integrated="true"] button:hover{transform:none;}
#workshop[data-integrated="true"] button:focus-visible,#workshop[data-integrated="true"] input:focus-visible,#workshop[data-integrated="true"] select:focus-visible,#workshop[data-integrated="true"] textarea:focus-visible{outline:2px solid var(--accent);outline-offset:3px;}
#workshop[data-integrated="true"] .shared-world-note{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px;line-height:1.7;margin:16px 0;}
#workshop[data-integrated="true"] .shared-world-note strong{color:var(--fg);}
#workshop[data-integrated="true"] .shared-world-note p{font-size:13px;margin:7px 0 0;color:var(--muted);}
#workshop[data-integrated="true"] .source-text{font-size:14px;line-height:1.75;}
#workshop[data-integrated="true"] input,#workshop[data-integrated="true"] textarea,#workshop[data-integrated="true"] select{color-scheme:inherit;}
#workshop[data-integrated="true"] .page-scroll{scroll-behavior:auto;scrollbar-color:var(--line) var(--bg);}
#workshop[data-integrated="true"] #ws-dialog{color-scheme:inherit;}
#workshop[data-integrated="true"] .dialog-body{min-height:0;overscroll-behavior:contain;}
#workshop[data-integrated="true"] .dialog-head,#workshop[data-integrated="true"] .dialog-foot{flex-shrink:0;}
@media(max-width:1050px){
 #workshop[data-integrated="true"] .app-shell{grid-template-columns:190px minmax(0,1fr);}
 #workshop[data-integrated="true"] .topbar{grid-template-areas:"crumb crumb" "suite suite" "search search";gap:8px;}
 #workshop[data-integrated="true"] .suite-header-actions{justify-content:flex-start;}
 #workshop[data-integrated="true"] .breadcrumb strong{max-width:70vw;}
}
@media(max-width:700px){
 #workshop[data-integrated="true"] .app-shell{grid-template-columns:64px minmax(0,1fr);}
 #workshop[data-integrated="true"] .sidebar{padding:16px 8px;gap:20px;}
 #workshop[data-integrated="true"] .brand{padding:0;justify-content:center;}
 #workshop[data-integrated="true"] .brand>div,#workshop[data-integrated="true"] .brand small,#workshop[data-integrated="true"] .nav-title,#workshop[data-integrated="true"] .recent-section,#workshop[data-integrated="true"] .side-footer{display:none;}
 #workshop[data-integrated="true"] .nav-link{padding:10px;justify-content:center;min-height:42px;position:relative;}
 #workshop[data-integrated="true"] .nav-count{position:absolute;right:0;top:0;}
 #workshop[data-integrated="true"] .summary-strip{grid-template-columns:1fr 1fr;gap:15px 0;}
 #workshop[data-integrated="true"] .summary-number{padding:0 15px;}
 #workshop[data-integrated="true"] .summary-number:nth-child(2){border-right:0;}
 #workshop[data-integrated="true"] .page-heading{align-items:flex-start;flex-wrap:wrap;gap:15px;}
 #workshop[data-integrated="true"] .command-trigger kbd{display:none;}
 #workshop[data-integrated="true"] .suite-world{flex:1;min-width:0;}
 #workshop[data-integrated="true"] .suite-world select{width:100%;min-width:0;}
 #workshop[data-integrated="true"] .suite-header-actions>.quiet{font-size:12px;padding:8px;min-height:38px;}
}
@media(max-width:440px){
 #workshop[data-integrated="true"]{--page-pad:14px;}
 #workshop[data-integrated="true"] .suite-world{flex-basis:100%;}
 #workshop[data-integrated="true"] .command-trigger span{font-size:11px;}
 #workshop[data-integrated="true"] .top-actions{gap:4px;}
 #workshop[data-integrated="true"] .page-heading h1{font-size:29px;}
 #workshop[data-integrated="true"] .form-grid{grid-template-columns:1fr;}
}
@media(prefers-reduced-motion:reduce){#workshop[data-integrated="true"] *,#workshop[data-integrated="true"] *::before,#workshop[data-integrated="true"] *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important;}}
#workshop[data-motion="off"] *,#workshop[data-motion="off"] *::before,#workshop[data-motion="off"] *::after{transition:none!important;animation:none!important;}

/* Error feedback belongs inside the native modal top layer, never behind masks. */
html[data-atelier-card-studio] #workshop .ws-modal-alerts{display:grid;gap:8px;max-height:180px;overflow:auto;margin:0 0 14px;}
html[data-atelier-card-studio] #workshop .ws-modal-alerts .toast{position:static;max-width:100%;min-width:0;overflow-wrap:anywhere;box-shadow:none;}
html[data-atelier-card-studio] #workshop .ws-modal-alerts .toast>span{min-width:0;}
html[data-atelier-card-studio] #workshop .modal-heading,html[data-atelier-card-studio] #workshop .modal-footer{flex:0 0 auto;}

/* rc3 discoverability: one source store, visible unfinished work and explicit approval. */
#workshop[data-integrated="true"] .main-nav{flex:0 0 auto;gap:3px;}
#workshop[data-integrated="true"] .sidebar{overflow-y:auto;overscroll-behavior:contain;gap:18px;}
#workshop[data-integrated="true"] .nav-link{font-size:12px;min-height:39px;line-height:1.4;}
#workshop[data-integrated="true"] .ws-authoring-workflow{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:14px 16px;margin:0 0 18px;background:var(--raised);border:1px solid var(--line);border-radius:14px;}
#workshop[data-integrated="true"] .ws-authoring-workflow>div:first-child{flex:1;min-width:180px;}
#workshop[data-integrated="true"] .ws-authoring-workflow strong{font:600 13px/1.5 "Segoe UI",system-ui,sans-serif;}
#workshop[data-integrated="true"] .ws-authoring-workflow small{display:block;font-size:12px;line-height:1.55;color:var(--muted);margin-top:3px;max-width:540px;}
#workshop[data-integrated="true"] .ws-authoring-workflow .row{flex:0 1 auto;}
#workshop[data-integrated="true"] .ws-draft-filters{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:16px;margin:0 0 18px;}
#workshop[data-integrated="true"] .ws-draft-batch{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px;font-size:13px;color:var(--muted);}
#workshop[data-integrated="true"] .ws-draft-results{display:grid;gap:12px;}
#workshop[data-integrated="true"] .ws-inbox-record{border:1px solid var(--line);border-radius:16px;padding:15px 18px;background:var(--panel);min-width:0;}
#workshop[data-integrated="true"] .ws-draft-meta{display:flex;flex-wrap:wrap;justify-content:space-between;gap:6px 16px;color:var(--muted);font-size:11px;line-height:1.5;padding-bottom:10px;border-bottom:1px solid var(--line);}
#workshop[data-integrated="true"] .ws-draft-meta>span{overflow-wrap:anywhere;min-width:0;}
#workshop[data-integrated="true"] .ws-inbox-record .draft-item{border:0;margin:10px 0 0;padding:0;background:none;}
#workshop[data-integrated="true"] .ws-inbox-record .draft-copy h3{font:600 15px/1.55 "Segoe UI",system-ui,sans-serif;overflow-wrap:anywhere;}
#workshop[data-integrated="true"] .ws-inbox-record .draft-copy p{font-size:13px;line-height:1.6;}
#workshop[data-integrated="true"] .ws-draft-pagination{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:20px 0;font-size:12px;color:var(--muted);}
#workshop[data-integrated="true"] .ws-import-card{max-width:1000px;padding:clamp(20px,3vw,36px);}
#workshop[data-integrated="true"] .ws-import-choices{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:25px 0;}
#workshop[data-integrated="true"] .ws-import-choice{display:flex;flex-direction:column;align-items:flex-start;gap:10px;padding:22px 18px;border:1px solid var(--line);border-radius:14px;background:var(--bg);text-align:left;white-space:normal;}
#workshop[data-integrated="true"] .ws-import-choice svg{color:var(--accent);}
#workshop[data-integrated="true"] .ws-import-choice strong{font-size:15px;line-height:1.4;}
#workshop[data-integrated="true"] .ws-import-choice small{font-size:12px;line-height:1.65;color:var(--muted);}
#workshop[data-integrated="true"] .ws-import-choice:hover{background:var(--raised);border-color:var(--accent);}
#workshop[data-integrated="true"] .ws-import-note{margin:24px 0 0;border-top:1px solid var(--line);padding-top:18px;}
@media(max-width:1100px){#workshop[data-integrated="true"] .ws-authoring-workflow{flex-wrap:wrap;}}
@media(max-width:760px){#workshop[data-integrated="true"] .ws-draft-filters,#workshop[data-integrated="true"] .ws-import-choices{grid-template-columns:1fr;}#workshop[data-integrated="true"] .ws-import-choice{gap:7px;padding:18px;}#workshop[data-integrated="true"] .ws-draft-meta{flex-direction:column;}#workshop[data-integrated="true"] .ws-authoring-workflow>div:first-child{min-width:0;}}

.figure-tile img[data-figure-index]:not([src]){display:block;width:100%;min-height:110px;background:var(--ws-panel,var(--panel,#283128));border-radius:10px;}
.figure-loading{display:block;padding:10px;font:12px/1.5 system-ui;color:inherit;opacity:.8}.figure-loading[hidden]{display:none}

#workshop #ws-destination-results{display:grid;gap:8px;margin-top:16px;max-height:48vh;overflow:auto;padding:3px}
#workshop .ws-destination{display:grid;grid-template-columns:minmax(0,1fr) auto;width:100%;text-align:left;gap:7px;padding:14px;border:1px solid var(--line);border-radius:12px;background:var(--panel);color:var(--text);font-size:14px}
#workshop .ws-destination span{min-width:0;overflow-wrap:anywhere}#workshop .ws-destination small{color:var(--muted);font-size:12px}#workshop .ws-destination:hover{border-color:var(--accent)}

web/home-shell.css:
/* rc4: task-first Home / Library / Tools. Scoped to Atelier's ShadowRoot.
   No card, native-home, engine or reviewer selectors. */
.layout .unified-topbar{position:sticky;top:0;z-index:30;display:grid;grid-template-columns:minmax(118px,1fr) minmax(0,auto);gap:12px;align-items:center;padding:14px 28px;min-height:78px;height:auto;background:var(--bg);border-bottom:1px solid var(--line-soft);box-shadow:none;}
.unified-topbar .topbar-left{min-width:0;display:flex;flex:initial;padding:0;align-self:center;}
.unified-topbar .owner-badge{font-size:12px;letter-spacing:0;line-height:1.4;text-transform:none;white-space:normal;text-align:left;}
.unified-topbar .top-actions{display:flex;flex-wrap:nowrap;min-width:0;gap:8px;align-items:center;}
.unified-topbar .search{display:flex;min-width:130px;width:clamp(140px,19vw,300px);max-width:300px;height:40px;}
.unified-topbar .search input{min-width:0;width:100%;font-size:13px;}
.unified-topbar :is(.add-cards-top,.browse-top,.sync-top){height:40px;min-height:40px;font-size:13px;padding:9px 13px;white-space:nowrap;}
.unified-topbar :is(.refresh-library,[data-action="appearance"]){height:38px;width:38px;flex:0 0 38px;}
.unified-topbar .sample-label{font-size:9px;letter-spacing:.4px;white-space:normal;}
.main-inner{padding:22px 28px 30px;max-width:1490px;}
.sidebar .nav-group{gap:2px;padding-bottom:14px;}
.sidebar .nav-row{min-height:38px;padding:8px 11px;font-size:13px;}
.sidebar .side-label{font-size:10px;letter-spacing:1.05px;}
.sidebar .tree-row{min-height:42px;padding-block:3px;max-height:none;transform:none;}
.sidebar .tree-name{line-height:1.45;font-size:12px;overflow-wrap:normal;word-break:normal;}
.sidebar .tree-open{min-width:0;min-height:34px;}
.sidebar .tree-open small{margin-left:auto;}
.sidebar .tree-art{width:25px;flex:0 0 25px;}
.sidebar .side-scroll{overflow-x:hidden;}
.layout[data-page="library"] .side-utility-links{padding-bottom:6px;}
.layout[data-page="library"] .recent-label,.layout[data-page="library"] .recent-links{display:none;}
/* Compact composition: usable lectures come before lower-priority modules. */
.task-focus.focus-panel.quiet-focus{grid-template-columns:minmax(0,1fr) minmax(210px,27%);}
.task-focus.quiet-focus .focus-intro{padding:25px 27px 24px;min-width:0;}
.task-focus.quiet-focus h1{font-size:clamp(25px,2.55vw,37px);line-height:1.13;max-width:26ch;font-weight:500;letter-spacing:-.85px;}
.task-focus.quiet-focus .eyebrow{font-size:10px;letter-spacing:1.35px;margin-bottom:13px;}
.task-focus.quiet-focus .focus-intro>p{margin-top:12px;max-width:60ch;font-size:13px;line-height:1.6;}
.task-focus .focus-actions{margin-top:18px;gap:9px;align-items:center;}
.task-focus .focus-actions :is(.primary,.secondary,.quiet){min-height:39px;font-size:12px;}
.task-focus.quiet-focus .focus-agenda{display:flex;flex-direction:column;justify-content:center;gap:11px;padding:21px 22px 20px 0;min-width:0;}
.task-focus .world-window{width:100%;height:174px;min-height:174px;border-radius:calc(var(--world-radius,20px) * .75);margin:0;}
.task-focus .world-window-label{padding:13px 15px;}
.task-focus .world-window-label strong{font-size:20px;line-height:1.15;}
.task-focus .focus-quiet-note{font-size:10px;line-height:1.55;color:var(--muted);display:flex;gap:7px;align-items:center;}
.task-focus .focus-footer{padding:12px 26px!important;gap:18px;}
.task-focus .focus-metric{padding-right:18px;gap:8px;}
.task-focus .focus-metric strong{font-size:23px;letter-spacing:-.6px;}
.task-focus .focus-metric span,.task-focus .scope-note{font-size:10px;}
.resume-lecture{display:flex;align-items:center;gap:11px;padding:12px 13px;background:var(--panel);border:1px solid var(--line-soft);border-radius:11px;margin-top:17px;max-width:650px;}
.resume-glyph{flex:0 0 25px;color:var(--tone);}
.resume-lecture>div{flex:1;min-width:0;}
.resume-lecture strong{display:block;font-size:14px;font-weight:600;line-height:1.45;overflow-wrap:anywhere;}
.resume-lecture small{display:block;font-size:10px;line-height:1.5;color:var(--muted);max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:3px;}
.resume-available{font-size:10px;color:var(--muted);white-space:nowrap;}
.desk-revisit{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-top:26px;}
.revisit-column{min-width:0;border:1px solid var(--line);background:var(--panel);border-radius:16px;padding:15px 18px;}
.revisit-column>header{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px;}
.revisit-column h2{font-size:15px;letter-spacing:-.25px;}
.revisit-column>header .quiet{font-size:11px;padding:5px;min-height:28px;}
.revisit-row{display:flex;gap:8px;align-items:center;border-top:1px solid var(--line-soft);padding:9px 0;}
.revisit-row>button:first-child{display:flex;gap:10px;align-items:center;flex:1;min-width:0;text-align:left;padding:3px;}
.revisit-row>button:first-child>span:last-child{min-width:0;flex:1;}
.revisit-row strong{display:block;font-size:12px;line-height:1.5;font-weight:600;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.revisit-row small{display:block;font-size:10px;line-height:1.55;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.revisit-row>button:hover strong{color:var(--accent-strong);}
.revisit-glyph{color:var(--tone);flex:0 0 20px;}
.revisit-empty{padding:14px 0 11px;color:var(--muted);font-size:12px;line-height:1.75;}
.desk-tools{margin-top:24px;}
.suite-exams{margin-top:28px;}
/* Library: navigation, collection edits and review actions have separate roles. */
.library{scroll-margin-top:106px;}
.library-orientation{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 16px;padding:10px 13px;border:1px solid var(--line-soft);background:var(--side);border-radius:10px;}
.library-orientation>span{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--muted);line-height:1.55;min-width:0;}
.library-orientation .quiet{font-size:11px;padding:4px 8px;min-height:28px;flex-shrink:0;}
.library .section-heading{align-items:flex-start;gap:17px;margin-bottom:16px;}
.library .section-heading h2{font-size:23px;font-weight:600;letter-spacing:-.55px;line-height:1.3;}
.library .section-heading p{font-size:12px;line-height:1.65;max-width:62ch;}
.library .library-actions{max-width:54%;gap:6px;}
.library-controls{gap:12px;}
.library-controls .view-tools{min-width:0;gap:10px;}
.library-controls select{min-width:0;max-width:100%;font-size:12px;}
.location-bar{margin-bottom:12px;}
.breadcrumbs{flex-wrap:wrap;row-gap:3px;min-width:0;}
.breadcrumbs .crumb{font-size:11px;max-width:250px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-height:30px;}
.cards:not(.list){grid-template-columns:repeat(auto-fill,minmax(min(100%,254px),1fr));gap:16px;}
.cards:not(.list) .deck-card{min-width:0;padding:19px 18px 0;}
.cards:not(.list) .card-head{margin-bottom:11px;}
.cards:not(.list) .card-art{width:44px;height:40px;}
.cards:not(.list) .card-art svg{width:44px;height:40px;}
.cards:not(.list) .card-title{font-size:16px;line-height:1.45;font-weight:600;}
.cards:not(.list) .card-description{font-size:11px;line-height:1.55;margin-top:6px;}
.cards:not(.list) .card-type{font-size:9px;letter-spacing:1px;}
.cards:not(.list) .card-bottom{margin-inline:-18px;}
.cards:not(.list) .card-peek{font-size:11px;border:1px solid var(--line-soft);margin-top:12px;padding:8px;}
.card-shortcuts .peek-row{display:flex;min-width:0;align-items:center;}
.card-shortcuts .peek-row>button:first-child{flex:1;min-width:0;}
.card-shortcuts .peek-row>button:first-child>span{white-space:normal;overflow-wrap:anywhere;line-height:1.5;}
/* Reset the old card-as-list positioning. The same IDs/actions/ordering survive. */
.cards.list{display:flex;flex-direction:column;gap:8px;}
.cards.list .library-row{display:block;min-height:0;padding:0;overflow:hidden;border:1px solid var(--line);border-radius:12px;background:var(--panel);box-shadow:none;transform:none;}
.library-row-main{display:grid;grid-template-columns:minmax(150px,1fr) minmax(125px,180px) auto;gap:14px;align-items:center;padding:13px 15px;min-width:0;}
.library-row-name{display:flex;align-items:center;min-width:0;gap:8px;}
.library-row-name>div{min-width:0;flex:1;}
.cards.list .library-row .card-title{display:block;grid-area:auto;font-size:14px;line-height:1.5;letter-spacing:0;text-align:left;white-space:normal;overflow-wrap:anywhere;}
.cards.list .library-row .card-path{grid-area:auto;max-width:100%;font-size:10px;margin-top:5px;}
.list-preview-toggle,.list-preview-spacer{width:26px;height:30px;flex:0 0 26px;}
.list-glyph{width:29px;flex:0 0 29px;color:var(--tone);}
.list-glyph svg{width:29px;height:30px;}
.list-meta{display:flex;gap:8px;flex-wrap:wrap;margin-top:5px;color:var(--muted);font-size:10px;align-items:center;}
.list-meta>span+span{border-left:1px solid var(--line);padding-left:8px;}
.list-meta .focus-badge{color:var(--accent-strong);font-weight:600;}
.row-counts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;text-align:right;font-size:13px;font-variant-numeric:tabular-nums;}
.row-counts small{display:block;color:var(--muted);font-size:9px;margin-top:2px;}
.library-row-actions{display:flex;align-items:center;gap:3px;}
.library-row-actions .icon-button{width:31px;flex:0 0 31px;height:33px;}
.library-row-actions .row-open{font-size:11px;min-height:32px;padding:6px;}
.cards.list .library-row-preview{border-top:1px solid var(--line-soft);padding:11px 16px 13px 60px;background:var(--side);}
.cards.list .library-row-preview .card-shortcuts{display:flex;max-width:100%;margin:0;padding:0;border:0;grid-area:auto;background:transparent;}
.cards.list .library-row-preview .peek-row{max-width:none;}
/* Tools: grouped, searchable native routes. Notes do not imply new confirmations. */
.tools-heading{padding:4px 0 17px!important;}
.tools-heading .eyebrow{margin-bottom:11px;}
.tools-heading h1{font-family:var(--studio-font);font-size:clamp(29px,3.3vw,44px);letter-spacing:-.9px;line-height:1.15;}
.tools-heading p{font-size:13px;line-height:1.7;color:var(--muted);margin-top:12px;}
.tools-spotlight{padding:13px 15px;background:var(--panel);border:1px solid var(--line);border-radius:13px;display:flex;gap:9px;flex-wrap:wrap;margin-bottom:21px;}
.tools-spotlight :is(.secondary,.quiet){font-size:12px;min-height:37px;}
.tools-filter-bar{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin-bottom:24px;}
.tool-categories{display:flex;gap:5px;flex-wrap:wrap;}
.tool-category{padding:8px 11px;border:1px solid transparent;border-radius:8px;color:var(--muted);font-size:12px;min-height:34px;line-height:1.5;}
.tool-category.selected{color:var(--accent-strong);background:var(--accent-soft);border-color:var(--line);}
.tool-category:hover{background:var(--raised);color:var(--text);}
.tool-result-count{font-size:11px;color:var(--muted);}
.tools-group{margin-top:23px;}
.tools-group-heading{display:flex;align-items:baseline;gap:15px;flex-wrap:wrap;margin-bottom:12px;}
.tools-group-heading h2{font-size:17px;letter-spacing:-.3px;text-transform:none;}
.tools-group-heading p{font-size:11px;color:var(--muted);}
.tools-grid{grid-template-columns:repeat(auto-fill,minmax(min(100%,275px),1fr));gap:11px;}
.tool-entry{border:1px solid var(--line);background:var(--panel);border-radius:13px;min-width:0;overflow:hidden;}
.tool-entry:focus-within{border-color:var(--accent);}
.tools-grid .tool-tile{border:0;border-radius:0;box-shadow:none;padding:17px 15px;display:flex;align-items:flex-start;gap:12px;min-height:129px;width:100%;height:100%;background:transparent;transform:none;}
.tools-grid .tool-tile:hover{background:var(--raised);transform:none;}
.tool-tile>span:nth-child(2){min-width:0;flex:1;}
.tool-tile>svg:last-child{margin-top:3px;color:var(--quiet);}
.tool-symbol{width:33px;height:35px;flex:0 0 33px;border-radius:9px;background:var(--accent-soft);color:var(--accent);display:grid;place-items:center;}
.tool-tile strong{font-size:13px;font-weight:600;line-height:1.5;display:block;}
.tool-tile small{display:block;font-size:11px;line-height:1.65;margin-top:6px;color:var(--muted);}
.tool-note{display:flex;align-items:flex-start;gap:5px;font-size:10px;line-height:1.6;color:var(--muted);margin-top:9px;}
.tool-note .icon{margin-top:2px;flex-shrink:0;}
.tool-entry:has(.tool-unavailable) .tool-tile{height:auto;opacity:.65;}
.tool-unavailable{display:block;font-size:11px;padding:0 15px 14px;color:var(--muted);line-height:1.6;}
.tool-safety{display:flex;align-items:flex-start;gap:13px;margin-top:28px;border:1px solid var(--line-soft);border-radius:12px;background:var(--side);padding:18px 20px;}
.tool-safety>span{color:var(--accent);padding-top:2px;}
.tool-safety strong{font-size:12px;}
.tool-safety p{font-size:11px;color:var(--muted);line-height:1.8;margin-top:5px;max-width:95ch;}
.tools-empty{margin:25px 0;}
@media(max-width:1250px){
 .layout .unified-topbar{grid-template-columns:minmax(0,1fr);gap:8px;padding-block:10px;}
 .unified-topbar .top-actions{width:100%;}
 .unified-topbar .search{flex:1;width:auto;max-width:none;}
 .library .library-actions{max-width:60%;}
 .library-row-main{grid-template-columns:minmax(150px,1fr) 140px;gap:10px;}
 .library-row-actions{grid-column:1/-1;justify-content:flex-end;border-top:1px solid var(--line-soft);padding-top:6px;}
 .library-row-actions .row-open{margin-right:auto;}
}
@media(max-width:980px){
 .task-focus.focus-panel.quiet-focus{grid-template-columns:minmax(0,1fr) 180px;}
 .task-focus.quiet-focus .focus-intro{padding:22px;}
 .task-focus .world-window{min-height:158px;height:158px;}
 .task-focus .world-window-label strong{font-size:18px;}
 .resume-available{display:none;}
 .library .section-heading{flex-direction:column;gap:12px;}
 .library .library-actions{max-width:100%;justify-content:flex-start;}
 .desk-revisit{gap:13px;}
 .task-focus .focus-footer{flex-wrap:wrap;gap:12px;}
 .task-focus .scope-note{margin-left:0;}
}
@media(max-width:820px){
 .layout .unified-topbar{display:flex;flex-direction:row;align-items:flex-start;gap:10px;padding:12px 17px;}
 .unified-topbar .topbar-left{flex:0 0 32px;min-width:0;padding-top:4px;}
 .unified-topbar .owner-badge,.unified-topbar .sample-label{display:none;}
 .unified-topbar .top-actions{flex:1;display:flex;flex-wrap:wrap;justify-content:flex-start;gap:7px;}
 .unified-topbar .search{flex:1 0 100%;min-width:0;height:37px;}
 .main-inner{padding:18px 20px 26px;}
 .library{scroll-margin-top:143px;}
}
@media(max-width:620px){
 .task-focus.focus-panel.quiet-focus{grid-template-columns:minmax(0,1fr);}
 .task-focus.quiet-focus .focus-agenda{padding:0 21px 19px;}
 .task-focus .world-window{height:90px;min-height:90px;}
 .task-focus .world-window-label{padding:10px 13px;}
 .task-focus .world-window-label strong{font-size:20px;}
 .focus-quiet-note{display:none!important;}
 .desk-revisit{grid-template-columns:1fr;}
 .library-controls{flex-wrap:wrap;align-items:center;}
 .library-controls>.tabs{max-width:100%;}
 .library-controls>.view-tools{flex:1;justify-content:flex-end;}
 .library-orientation{align-items:flex-start;}
 .library-orientation .quiet{padding:4px;}
 .breadcrumbs .crumb{max-width:180px;}
 .parent-link{display:none;}
 .cards.list .library-row-main{grid-template-columns:minmax(0,1fr);padding:12px;gap:11px;}
 .row-counts{grid-template-columns:repeat(3,minmax(0,1fr));text-align:left;padding-left:64px;}
 .row-counts span{display:flex;gap:5px;align-items:baseline;font-size:12px;}
 .row-counts small{margin:0;}
 .library-row-actions{grid-column:auto;}
 .cards.list .library-row-preview{padding:12px 14px;}
 .list-meta{gap:5px;}
 .library-row-actions .icon-button{width:34px;flex-basis:34px;}
 .tools-spotlight{padding:12px;gap:7px;}
 .tool-category{font-size:11px;padding:7px 9px;}
 .tools-group-heading{gap:4px;flex-direction:column;}
 .tools-grid{grid-template-columns:minmax(0,1fr);}
}
@media(max-width:410px){
 .main-inner{padding:15px 12px 24px;}
 .layout .unified-topbar{padding:10px 11px;gap:6px;}
 .unified-topbar .top-actions{gap:5px;}
 .unified-topbar :is(.add-cards-top,.browse-top,.sync-top){padding:8px 9px;font-size:11px;gap:5px;height:36px;min-height:36px;}
 .unified-topbar :is(.add-cards-top,.browse-top,.sync-top)>svg{display:none;}
 .unified-topbar :is(.refresh-library,[data-action="appearance"]){height:33px;width:29px;flex:0 0 29px;}
 .task-focus.quiet-focus .focus-intro{padding:20px!important;}
 .task-focus.quiet-focus h1{font-size:27px;}
 .task-focus .focus-footer{padding:12px 19px!important;}
 .task-focus .focus-metric{gap:6px;padding-right:11px;}
 .task-focus .focus-metric strong{font-size:21px;}
 .task-focus .focus-metric span{font-size:9px;}
 .task-focus .scope-note{width:100%;}
 .task-focus .focus-actions .quiet{padding-left:0;}
 .library .section-heading h2{font-size:21px;}
 .library-orientation{gap:6px;}
 .library-orientation>span{font-size:10px;}
 .library-orientation>span>svg{display:none;}
 .row-counts{padding-left:0;justify-content:space-between;gap:6px;}
}
:host([data-density="compact"]) .cards.list .library-row-main{padding-block:9px;}
:host([data-motion="off"]) :is(.tool-tile,.library-row,.revisit-row button),
:host([data-companion="true"]) .task-focus{transition:none;}
@media(prefers-reduced-motion:reduce){.task-focus *, .tools-page *, .library *{transition:none!important;animation:none!important;scroll-behavior:auto!important;}}
/* Match the specificity of the existing world composition, keeping its art/font/radius. */
:host([data-owner="atelier"]) .task-focus.quiet-focus{grid-template-columns:minmax(0,1fr) minmax(210px,27%);}
:host([data-owner="atelier"]) .task-focus.quiet-focus .focus-intro{display:block;padding:25px 27px 23px;}
:host([data-owner="atelier"]) .task-focus.quiet-focus h1{font-size:clamp(26px,2.5vw,36px);line-height:1.13;letter-spacing:-.8px;max-width:none;margin:0;text-wrap:pretty;}
:host([data-owner="atelier"]) .task-focus.quiet-focus .focus-intro>p{margin-top:12px;font-size:13px;line-height:1.6;max-width:60ch;}
:host([data-owner="atelier"]) .task-focus .focus-actions{margin-top:17px;}
:host([data-owner="atelier"]) .task-focus .focus-agenda{display:flex;flex-direction:column;padding:21px 22px 20px 0;}
:host([data-owner="atelier"]) .cards.list .library-row .card-title{font-family:"Segoe UI",system-ui,sans-serif;font-weight:600;}
:host([data-owner="atelier"]) .tools-heading h1{font-family:var(--world-font);}
@media(max-width:980px){
 :host([data-owner="atelier"]) .task-focus.quiet-focus{grid-template-columns:minmax(0,1fr) 180px;}
 :host([data-owner="atelier"]) .task-focus.quiet-focus .focus-intro{padding:22px;}
}
@media(max-width:620px){
 :host([data-owner="atelier"]) .task-focus.quiet-focus{grid-template-columns:minmax(0,1fr);}
 :host([data-owner="atelier"]) .task-focus .focus-agenda{padding:0 21px 19px;}
 :host([data-owner="atelier"]) .task-focus.quiet-focus h1{font-size:27px!important;}
}
@media(forced-colors:active){
 .tool-entry,.library-row,.resume-lecture,.revisit-column,.library-orientation{border:1px solid CanvasText;}
 .tool-category.selected,.list-meta .focus-badge{outline:1px solid Highlight;}
 .tool-symbol,.resume-glyph,.revisit-glyph{color:ButtonText;}
}
/* A leaf deck is a study destination, not an empty-folder dead end. */
.deck-detail{border:1px solid var(--line);border-radius:var(--world-radius,18px);background:var(--panel);padding:26px;}
.deck-detail-head{display:flex;align-items:center;gap:16px;}
.detail-glyph{width:46px;flex:0 0 46px;color:var(--tone);}
.detail-glyph svg{width:46px;height:44px;}
.deck-detail h3{font-size:20px;letter-spacing:-.35px;line-height:1.3;}
.deck-detail-head p{font-size:12px;line-height:1.7;color:var(--muted);margin-top:7px;}
.deck-detail-counts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:25px;border-block:1px solid var(--line-soft);padding:18px 0;}
.deck-detail-counts strong{display:block;font-size:27px;font-weight:500;font-variant-numeric:tabular-nums;line-height:1.3;}
.deck-detail-counts span{display:block;font-size:11px;color:var(--muted);margin-top:5px;}
.deck-detail-actions{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-top:21px;}
.deck-detail-actions button{min-height:38px;font-size:12px;}
.detail-note{display:flex;align-items:flex-start;gap:8px;font-size:11px;line-height:1.7;color:var(--muted);margin-top:20px;}
.detail-note .icon{margin-top:2px;}
@media(max-width:500px){.deck-detail{padding:19px}.deck-detail h3{font-size:19px}.deck-detail-head{gap:11px}.detail-glyph{width:34px;flex-basis:34px}.detail-glyph svg{width:34px}.deck-detail-counts{gap:10px}.deck-detail-counts span{font-size:10px}.deck-detail-counts strong{font-size:25px}}

/* One read-only authoring projection; actions open the single source workspace. */
.authoring-hub{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:18px;padding:24px;margin:22px 0;border:1px solid var(--line);border-radius:18px;background:var(--panel);}
.authoring-hub h2{font-size:21px;letter-spacing:-.4px;}.authoring-hub .eyebrow{font-size:9px;margin-bottom:7px;}.authoring-hub p{font-size:12px;color:var(--muted);margin-top:7px;}
.authoring-hub-actions{display:flex;flex-wrap:wrap;gap:8px;}.authoring-hub-actions button{font-size:12px;min-height:38px;}
@media(max-width:640px){.authoring-hub{padding:18px}.authoring-hub-actions{width:100%}.authoring-hub-actions button{flex:1;min-width:120px;}}

.widget-presets{display:grid;gap:12px;padding:18px;border:1px solid var(--line);border-radius:14px;background:var(--raised);margin-bottom:20px;}.widget-presets small{display:block;color:var(--muted);font-size:12px;line-height:1.6;margin-top:5px;}.widget-presets>div:last-child{display:flex;gap:8px;flex-wrap:wrap;}.widget-presets [aria-pressed="true"]{outline:2px solid var(--accent);outline-offset:2px;}

/* rc3 usability audit: unfinished work is a task queue, not another hero. */
.workflow-inbox{margin:0 0 20px;padding:14px 16px;border:1px solid var(--line-soft);border-radius:16px;background:var(--side);color:var(--text);}
.workflow-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;}
.workflow-heading>strong{font-size:13px;letter-spacing:0;}
.workflow-heading .quiet{font-size:12px;min-height:34px;}
.workflow-inbox>p{font-size:12px;color:var(--muted);margin:8px 0 0;line-height:1.65;}
.workflow-items{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,225px),1fr));gap:8px;margin-top:10px;}
.workflow-item{display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--line);border-radius:11px;background:var(--panel);color:var(--text);text-align:left;min-width:0;min-height:58px;}
.workflow-item>span:nth-child(2){flex:1;min-width:0;}
.workflow-item strong{font:600 12px/1.4 "Segoe UI",system-ui,sans-serif;display:block;}
.workflow-item small{display:block;font-size:11px;color:var(--muted);line-height:1.5;overflow-wrap:anywhere;}
.workflow-item:hover{background:var(--raised);border-color:var(--accent);transform:none;}
.workflow-glyph{color:var(--accent);display:grid;place-content:center;flex:0 0 22px;}
.practice-plan-picker{display:grid;gap:10px;}
.practice-plan-picker>button{display:flex;align-items:center;gap:12px;width:100%;padding:14px;border:1px solid var(--line);border-radius:12px;background:var(--panel);color:var(--text);}
.practice-plan-picker>button>span:nth-child(2){flex:1;min-width:0;text-align:left;}
.practice-plan-picker strong,.practice-plan-picker small{display:block;overflow-wrap:anywhere;}
.practice-plan-picker small{margin-top:4px;color:var(--muted);font-size:12px;}
.practice-plan-picker>button:hover{background:var(--raised);border-color:var(--accent);}

/* Functional labels must be readable without zooming into decorative metadata. */
.side-utilities button,.side-quick button,.scope-bar .quiet,.scope-bar>span:first-child,.scope-bar select,.library-actions .quiet,.library-actions .secondary,.parent-link,.exam-section-actions .quiet,.help-strip .quiet,.library-controls :is(select,button),.peek-more,.tree-open,.nav-group .nav-row,.side-links button{font-size:13px!important;line-height:1.5!important;}
.library-foot,.countline,.card-description,.card-path,.scope-note,.row-counts small,.lecture-counts small,.note{font-size:12px!important;line-height:1.5!important;}
.focus-card{grid-template-columns:minmax(0,1fr) minmax(230px,32%)!important;}.focus-agenda{min-width:0;}.focus-intro{min-width:0;}
@media(max-width:850px){.focus-card{grid-template-columns:minmax(0,1fr)!important}}

/* Release finish: same bounded, accessible dialog system for progress/export. */
.export-controls,.progress-controls{display:flex;align-items:flex-end;gap:12px;flex-wrap:wrap;margin-bottom:18px}
.export-controls label,.progress-controls label{display:grid;gap:8px;font-size:13px;font-weight:600;min-width:0;flex:1 1 150px}
.export-controls label:first-child{flex:3 1 240px}
.export-controls input,.export-controls select,.progress-controls select{width:100%;min-height:42px;font-size:14px}
.export-list{display:grid;gap:8px;margin:12px 0 18px}
.export-row{display:flex;align-items:center;gap:13px;width:100%;min-width:0;min-height:74px;padding:14px;border:1px solid var(--line);border-radius:12px;background:var(--panel)}
.export-row:hover{border-color:var(--accent);background:var(--raised)}
.export-row>span:nth-child(2){flex:1;min-width:0;display:grid;gap:5px}
.export-row strong{font-size:14px;overflow-wrap:anywhere}.export-row small{font-size:12px;line-height:1.4;color:var(--muted);overflow-wrap:anywhere}
.export-icon{flex:0 0 36px;display:grid;place-content:center;color:var(--accent)}
.progress-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:12px 0 24px}
.progress-summary>div{display:grid;gap:10px;padding:16px 12px;border:1px solid var(--line);border-radius:14px;background:var(--panel)}
.progress-summary strong{font-size:26px;letter-spacing:-.6px;font-variant-numeric:tabular-nums;line-height:1.2}
.progress-summary span{font-size:12px;line-height:1.4;color:var(--muted)}
.progress-chart{padding:18px 14px 12px;background:var(--panel);border:1px solid var(--line);border-radius:16px;margin-bottom:18px;overflow-x:auto}
.progress-bars{display:flex;gap:6px;align-items:stretch;height:165px;min-width:240px}
.progress-day{flex:1;min-width:5px;display:flex;flex-direction:column;justify-content:flex-end;align-items:stretch;position:relative;padding-bottom:24px}
.progress-day>div{height:var(--bar-height);max-height:140px;min-height:2px;background:linear-gradient(0deg,var(--accent-soft),var(--accent));border-radius:5px 5px 2px 2px}
.progress-day small{position:absolute;bottom:0;left:50%;transform:translateX(-50%);font-size:10px;color:var(--muted);white-space:nowrap}
.progress-bars:has(.progress-day:nth-child(8)) .progress-day small{display:none}
.progress-bars:has(.progress-day:nth-child(8)) .progress-day:first-child small,.progress-bars:has(.progress-day:nth-child(8)) .progress-day:last-child small{display:block}
.progress-detail{border:1px solid var(--line);border-radius:12px;padding:14px;margin:16px 0;overflow-x:auto;font-size:13px;line-height:1.7}
.progress-detail summary{cursor:pointer;font-weight:600}.progress-detail table{width:100%;border-collapse:collapse;margin:14px 0;text-align:right;font-variant-numeric:tabular-nums}
.progress-detail th,.progress-detail td{padding:8px;border-bottom:1px solid var(--line-soft);font-size:12px;white-space:nowrap}.progress-detail th:first-child,.progress-detail td:first-child{text-align:left}
.progress-deck-title{font-size:17px;margin:22px 0 12px}.progress-decks{display:grid;gap:8px;margin-bottom:18px}
.progress-decks>div{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:6px 16px;border-bottom:1px solid var(--line-soft);padding:12px 0;font-size:13px}
.progress-decks span{overflow-wrap:anywhere}.progress-decks strong{font-variant-numeric:tabular-nums}.progress-decks small{grid-column:2;color:var(--muted)}
@media(max-width:600px){.progress-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.export-controls,.progress-controls{gap:10px}.progress-summary strong{font-size:24px}}
@media(prefers-reduced-motion:reduce){.export-row{transition:none}}
/* Real control classes (not only their container aliases): keep essentials readable. */
.recent-link,.native-link{font-size:13px!important;line-height:1.5!important;min-height:32px;}

web/native-widgets.css:
/* Owned ShadowRoot only. Provider/card/media DOM is never sized by these rules. */
.layout[data-page="widgets"] .main-inner{max-width:1280px;padding:24px clamp(18px,3vw,42px) 36px;margin:0 auto;width:100%;}
.layout[data-page="widgets"] .nw-header{height:auto;min-height:94px;padding:22px clamp(18px,3vw,42px);gap:16px;display:flex;align-items:center;justify-content:space-between;}
.nw-header-title{display:flex;gap:15px;align-items:center;min-width:0;}
.nw-header-title small{display:block;color:var(--muted);font-size:12px;letter-spacing:.5px;margin-bottom:5px;}
.nw-header-title h1{font-family:var(--world-font);font-size:30px;line-height:1.15;letter-spacing:-.7px;color:var(--text);}
.nw-header-controls{display:flex;align-items:center;gap:10px;flex-shrink:0;}
.nw-header-controls .icon-button{height:40px;width:40px;}
.native-widgets{min-width:0;}
.nw-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:10px;padding:0 0 24px;border-bottom:1px solid var(--line);}
.nw-toolbar .primary,.nw-toolbar .secondary,.nw-toolbar .quiet{min-height:42px;font-size:14px;display:inline-flex;align-items:center;gap:8px;}
.nw-toolbar .quiet{margin-left:8px;}
.nw-section-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:24px 0 16px;color:var(--muted);font-size:13px;line-height:1.5;}
.nw-section-heading h2{color:var(--text);font-size:20px;}
.nw-section-heading>span{font-size:12px;}
.nw-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;align-items:start;}
.nw-card{min-width:0;background:linear-gradient(135deg,var(--panel),var(--side));border:1px solid var(--line);border-radius:var(--world-radius,20px);padding:22px 24px 0;box-shadow:inset 0 1px 0 var(--sheen,rgba(255,255,255,.05)),0 10px 28px var(--shadow);overflow:hidden;}
.nw-wide{grid-column:1/-1;}
.nw-card[data-native-widget="today"]{background:linear-gradient(112deg,var(--hero),var(--hero-end));}
.nw-card-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:20px;min-width:0;}
.nw-title-mark{display:flex;align-items:center;gap:10px;min-width:0;}
.nw-title-mark>.icon{color:var(--accent);}
.nw-title-mark h2{font-family:"Segoe UI",system-ui,sans-serif;font-size:16px;font-weight:650;line-height:1.4;letter-spacing:-.2px;overflow-wrap:anywhere;}
.nw-caption{font-size:12px;color:var(--muted);line-height:1.5;max-width:50%;text-align:right;overflow-wrap:anywhere;}
.nw-today-content{display:grid;grid-template-columns:minmax(0,1fr) minmax(180px,28%);gap:32px;align-items:center;}
.nw-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;}
.nw-metrics strong{display:block;font-family:"Segoe UI",system-ui,sans-serif;font-weight:550;font-size:38px;font-variant-numeric:tabular-nums;letter-spacing:-1px;line-height:1.3;}
.nw-metrics span{display:block;color:var(--muted);font-size:12px;line-height:1.4;margin-top:6px;}
.nw-definitions{color:var(--muted);font-size:12px;line-height:1.65;max-width:570px;margin:18px 0 4px;}
.nw-week{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px;height:98px;}
.nw-day{position:relative;display:flex;align-items:flex-end;justify-content:center;border-bottom:1px solid var(--line);padding-bottom:17px;}
.nw-day>span{height:calc(var(--level)*.72);min-height:3px;width:70%;max-width:24px;border-radius:4px 4px 0 0;background:var(--accent);opacity:.45;}
.nw-day.is-today>span{opacity:1;}
.nw-day small{font-size:10px;line-height:12px;position:absolute;bottom:0;color:var(--muted);}
.nw-link-list{min-width:0;}
.nw-focus-row{display:flex;align-items:center;gap:4px;border-top:1px solid var(--line-soft);}
.nw-focus-row:first-child{border-top:0;}
.nw-focus-row .icon-button{flex:0 0 32px;height:32px;width:32px;color:var(--muted);}
.nw-open{display:flex;align-items:center;gap:12px;min-width:0;flex:1;width:100%;padding:12px 2px;border-radius:7px;color:var(--text);font-size:14px;}
.nw-open:hover{background:var(--hover);}
.nw-open>span:not(.nw-date):not(.nw-dot){display:block;flex:1;min-width:0;}
.nw-open strong{display:block;font-size:14px;line-height:1.5;font-weight:600;overflow-wrap:anywhere;}
.nw-open small{display:block;font-size:12px;line-height:1.5;color:var(--muted);margin-top:4px;overflow-wrap:anywhere;}
.nw-dot{height:6px;width:6px;flex:0 0 6px;border-radius:50%;background:var(--accent);}
.nw-date{display:grid;place-items:center;flex:0 0 36px;height:36px;color:var(--accent);background:var(--accent-soft);border-radius:10px;}
.nw-plan+.nw-plan{border-top:1px solid var(--line-soft);}
.nw-card-footer{border-top:1px solid var(--line-soft);margin:18px -24px 0;padding:10px 16px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;min-height:52px;background:var(--material,transparent);}
.nw-card-footer .quiet{display:inline-flex;align-items:center;gap:7px;font-size:13px;min-height:34px;padding:5px 8px;}
.nw-card-footer .nw-caption{margin-left:auto;}
.nw-work-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;}
.nw-work-link{display:flex;align-items:center;gap:12px;padding:12px;background:var(--raised);border:1px solid var(--line-soft);border-radius:12px;min-height:76px;}
.nw-work-link>.icon{color:var(--accent);}
.nw-work-link>span{min-width:0;}
.nw-work-link strong,.nw-work-empty strong{display:block;font-size:14px;font-weight:600;line-height:1.5;}
.nw-work-link small,.nw-work-empty small{display:block;font-size:12px;color:var(--muted);line-height:1.6;margin-top:4px;}
.nw-work-empty{padding:12px;border:1px dashed var(--line);border-radius:12px;}
.nw-state{font-size:14px;line-height:1.8;color:var(--muted);margin:10px 0 24px;overflow-wrap:anywhere;}
.nw-empty{grid-column:1/-1;padding:38px 26px;background:var(--panel);border:1px dashed var(--line);border-radius:20px;text-align:center;}
.nw-empty h2{font-size:24px;margin:0 0 10px;}
.nw-empty p{font-size:14px;line-height:1.7;margin:10px auto 20px;color:var(--muted);max-width:480px;}
.nw-empty .primary{display:inline-flex;align-items:center;gap:8px;}
.nw-bottom-note{color:var(--quiet);font-size:12px;line-height:1.65;margin:20px 0 0;}
.nw-on-home{margin:20px 0 28px;}
.nw-note-text{white-space:pre-wrap;font-size:15px;line-height:1.8;overflow-wrap:anywhere;max-height:300px;overflow:auto;margin:4px 0 18px;}
.nw-note-label{display:block;font-weight:600;line-height:1.6;}
#nw-note-input{box-sizing:border-box;display:block;width:100%;max-width:100%;min-height:180px;max-height:50vh;resize:vertical;background:var(--panel);border:1px solid var(--line);border-radius:10px;color:var(--text);font:15px/1.7 "Segoe UI",system-ui,sans-serif;padding:14px;margin-top:10px;}
.nw-arranged-list{display:grid;gap:10px;}
.nw-arranged{display:flex;align-items:center;gap:12px;flex-wrap:wrap;border:1px solid var(--line);border-radius:12px;background:var(--panel);padding:12px;}
.nw-arranged-label{flex:1;min-width:120px;}
.nw-arranged-label strong{display:block;font-size:14px;overflow-wrap:anywhere;}
.nw-arranged-label small{display:block;font-size:11px;line-height:1.6;color:var(--muted);margin-top:4px;}
.nw-arranged-options{display:flex;gap:14px;align-items:center;flex-wrap:wrap;}
.nw-arranged-options label{display:flex;align-items:center;gap:7px;font-size:12px;line-height:1.5;}
.nw-arranged-options select{font-size:12px;padding:6px 8px;}
.nw-arranged-move{display:flex;gap:2px;}
.nw-arranged-move .icon-button{width:32px;height:34px;}
.nw-add-heading{font-size:16px;margin:24px 0 14px;}
.nw-catalog{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;}
.nw-catalog-item{display:flex;gap:12px;align-items:center;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px;min-width:0;}
.nw-catalog-item>.icon{color:var(--accent);}
.nw-catalog-item>span{flex:1;min-width:0;}
.nw-catalog-item strong{font-size:14px;display:block;line-height:1.5;overflow-wrap:anywhere;}
.nw-catalog-item small{font-size:12px;display:block;color:var(--muted);line-height:1.6;margin-top:5px;}
.nw-provider-help{font-size:13px;line-height:1.75;margin-top:22px;color:var(--muted);}
.nw-provider-help summary{cursor:pointer;}
.nw-provider-help p{margin-top:10px;}
.nw-tools-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;}
.nw-tool{display:flex;align-items:center;gap:12px;font-size:14px;min-height:46px;padding:12px;border:1px solid var(--line-soft);background:var(--panel);border-radius:10px;}
.nw-tool:hover,.nw-catalog-item:hover{border-color:var(--accent);background:var(--raised);}
.nw-tool>.icon{color:var(--accent);}
.nw-card [data-native-provider]{display:block;min-width:0;max-width:100%;padding-bottom:22px;}
.nw-card:not(.nw-wide) .nw-today-content{grid-template-columns:1fr;gap:18px;}
.nw-card:not(.nw-wide) .nw-metrics{gap:10px;}
.nw-card:not(.nw-wide) .nw-metrics strong{font-size:30px;}
@media(max-width:1100px){.nw-today-content{grid-template-columns:1fr;gap:16px}.nw-week{height:68px;max-width:360px}.nw-grid{gap:14px}.nw-metrics strong{font-size:32px}.nw-card{padding:18px 18px 0}.nw-card-footer{margin-left:-18px;margin-right:-18px}.nw-caption{max-width:44%}}
@media(max-width:760px){.nw-grid{grid-template-columns:minmax(0,1fr)}.nw-card-heading{flex-wrap:wrap}.nw-caption{max-width:100%;text-align:left}.layout[data-page="widgets"] .nw-header{flex-wrap:wrap;min-height:0;padding-top:16px;padding-bottom:16px}.nw-header-title h1{font-size:26px}.nw-header-controls{margin-left:auto}.nw-section-heading>span{display:none}.nw-catalog{grid-template-columns:1fr}.nw-tools-list{grid-template-columns:1fr}.nw-arranged{gap:10px}.nw-arranged-label{min-width:130px}.nw-arranged-options{order:3;width:100%}.nw-toolbar .quiet{margin-left:0}.nw-card-footer .nw-caption{margin-left:0}.nw-metrics span{font-size:12px}.nw-header-controls .secondary{font-size:13px;padding:8px 10px}.nw-header-title small{display:none}}
@media(prefers-reduced-motion:reduce){.native-widgets *, .nw-on-home *{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
:host([data-motion="off"]) .native-widgets *, :host([data-motion="off"]) .nw-on-home *{animation:none!important;transition:none!important}
@media(forced-colors:active){.nw-card,.nw-catalog-item,.nw-tool,.nw-arranged{border:1px solid CanvasText}.nw-day>span,.nw-dot{background:Highlight}.nw-date{color:CanvasText}}

web/review-finish.css:
/* Reader-first finish. No sizing, wrapping, transforms or card selectors added. */
html[data-atelier-screen="review"] #atelier-review-header button:focus-visible,
html[data-atelier-screen="review-bottom"][data-atelier-toolbar="stock"] #outer button:focus-visible{outline:2px solid var(--at-accent-strong)!important;outline-offset:3px!important;box-shadow:0 0 0 2px var(--at-side)!important;}
html[data-atelier-screen="review-bottom"][data-atelier-toolbar="stock"] #outer button{transition:background-color .14s ease,border-color .14s ease!important;transform:none!important;}
html[data-atelier-motion="off"][data-atelier-screen="review-bottom"] #outer button{transition:none!important;}
@media(prefers-reduced-motion:reduce){html[data-atelier-screen="review-bottom"] #outer button{transition:none!important;}}
@media(forced-colors:active){html[data-atelier-screen="review-bottom"] #outer button:focus-visible{outline:2px solid Highlight!important;box-shadow:none!important;}}

web/reviewer.js:
/* Presentation only. Layout-only bridge; no answer handlers, template edits, scheduling or keys. */
(() => {
  'use strict';
  const start=()=>{
    const boot=document.getElementById('atelier-review-boot');
    if(!boot||window.AtelierReview)return;
    let config;try{config=JSON.parse(boot.textContent);}catch(_){return;}
    const root=document.documentElement;
    let lastGeometry='', geometryTimer=null, observedOuter=null, footerObserver=null;
    let info=window.__atelierReviewCard||{eligible:false,path:[],stage:'question'},header=null,scheduled=false,resetQuestion=false;
    let gapOriginal=null,gapNode=null,qaSizeObserver=null,observedQA=null,alignFrame=0,settleUntil=0,userMoved=false,paintKey='',disposed=false;
    const keyOf=x=>String(x?.id||'')+':'+String(x?.stage||'question');
    // Keep all flags/classes/styles owned by the card and every node in #qa.
    // Advanced/IO layouts retain their exact canvas and image geometry.
    function complexContent(){
      const qa=document.getElementById('qa');
      if(!qa)return true;
      return info.protected===true || !!qa.querySelector('canvas,iframe,object,embed,#image-occlusion-container,#image-occlusion-canvas,[id^=io-],[id^=io_],[data-occlusions],.io-overlay,.io-wrapper,.io-mask,.image-occlusion') || /(?:image.occlusion|io[-_](?:overlay|wrapper|qmask|amask|original|container))/i.test(qa.innerHTML) || [...qa.querySelectorAll('[style]')].some(e=>/position\s*:\s*(absolute|fixed|sticky)|transform\s*:|zoom\s*:/.test(e.getAttribute('style')||''));
    }
    function imageOcclusion(){
      if(info.protected===true)return false;
      const qa=document.getElementById('qa');
      return !!qa?.querySelector('#image-occlusion-container,#image-occlusion-canvas,#io-wrapper,#io-overlay,[data-occlusions],.io-wrapper,.io-overlay') || info.imageOcclusion===true;
    }
    // Only own #qa's top gap for eligible reading cards; never resize, wrap or
    // transform the original image/canvas/masks. Restore the latest foreign value.
    function releaseGap(){
      if(gapNode&&gapOriginal&&gapNode.style.getPropertyValue('margin-top')===gapOriginal.applied&&gapNode.style.getPropertyPriority('margin-top')==='important'){
        if(gapOriginal.value)gapNode.style.setProperty('margin-top',gapOriginal.value,gapOriginal.priority);else gapNode.style.removeProperty('margin-top');
      }
      gapNode=null;gapOriginal=null;
    }
    function ownGap(qa){
      if(gapNode!==qa){releaseGap();gapNode=qa;}
      const v=qa.style.getPropertyValue('margin-top'),p=qa.style.getPropertyPriority('margin-top'),desired=config.context==='hidden'?'auto':'0px';
      if(gapOriginal&&v===gapOriginal.applied&&p==='important'){if(v!==desired){qa.style.setProperty('margin-top',desired,'important');gapOriginal.applied=desired;}return;}
      gapOriginal={value:v,priority:p,applied:desired};qa.style.setProperty('margin-top',desired,'important');
    }
    function observeSize(qa){
      if(observedQA===qa)return;
      qaSizeObserver?.disconnect();observedQA=qa;
      if(qa&&window.ResizeObserver){qaSizeObserver=new ResizeObserver(scheduleLayout);qaSizeObserver.observe(qa);}
    }
    function settleLayout(){
      alignFrame=0;
      if(disposed||config.screen!=='review'||root.dataset.atelierCard!=='reading')return;
      const qa=document.getElementById('qa');if(!qa)return;
      ownGap(qa);observeSize(qa);
      const clearance=Math.max(0,Number(window.onigiriReviewerHeaderOffsetPx)||0);
      const v=clearance+'px';if(root.style.getPropertyValue('--atelier-header-clearance')!==v)root.style.setProperty('--atelier-header-clearance',v);
      const st=getComputedStyle(document.body),qr=qa.getBoundingClientRect();
      const hr=header?.isConnected?header.getBoundingClientRect():null;
      const pad=parseFloat(st.paddingTop)+parseFloat(st.paddingBottom);
      const total=qr.height+(hr?hr.height+10:0)+pad;
      root.dataset.atelierFit=total<=innerHeight+1?'fits':'scroll';
      // Counter Anki's delayed answer scroll ONLY when the whole reading card fits.
      // Long answers retain native answer-anchor scrolling and manual scrolling wins.
      if(!userMoved && performance.now()<settleUntil && (resetQuestion||total<=innerHeight+1)){
        window.scrollTo({top:0,left:0,behavior:'instant'});resetQuestion=false;
      }
    }
    function scheduleLayout(){if(!alignFrame&&!disposed)alignFrame=requestAnimationFrame(settleLayout);}
    function newPaint(value){
      const key=keyOf(value);if(key!==paintKey){paintKey=key;userMoved=false;settleUntil=performance.now()+1600;resetQuestion=value?.stage==='question';if(header){header.dataset.expanded='false';const b=header.querySelector('button');if(b){b.setAttribute('aria-expanded','false');b.textContent='Details';}}}
      info=value||{eligible:false,path:[]};queue();scheduleLayout();
    }
    function stockFooter(){
      const outer=document.getElementById('outer'),table=document.getElementById('innertable'),middle=document.getElementById('middle');
      if(!outer||!table||!middle||!outer.contains(table)||!table.contains(middle))return false;
      // A replacement bar owns its own sizing. Fail closed when the native
      // three-cell row is no longer present, rather than breaking its layout.
      const row=table.tBodies[0]?.rows[0];
      return !!row && row.cells.length>=3 && Array.from(row.cells).includes(middle) &&
        row.cells[0].classList.contains('stat') && row.cells[row.cells.length-1].classList.contains('stat');
    }
    function measureFooter(){
      if(config.screen!=='review-bottom'||config.style==='off'||!stockFooter())return null;
      const outer=document.getElementById('outer'),r=outer.getBoundingClientRect();
      const height=Math.ceil(Math.max(r.height,outer.scrollHeight)+Math.max(0,r.top)+2);
      return {token:config.layoutToken,height,width:root.clientWidth,version:config.version||'1.0.2'};
    }
    function requestFooterFit(force=false){
      if(config.screen!=='review-bottom')return;
      clearTimeout(geometryTimer);
      geometryTimer=setTimeout(()=>{
        const outer=document.getElementById('outer');
        if(!outer)return;
        const key=[Math.ceil(outer.getBoundingClientRect().height),document.documentElement.clientWidth,window.innerHeight,root.dataset.atelierToolbar||'native',config.style].join(':');
        if(key===lastGeometry&&!force)return;lastGeometry=key;
        if(typeof window.pycmd==='function'&&config.layoutToken){
          window.pycmd('atelier:review-layout:'+config.layoutToken);
        }
        // Offline preview listens here; native Anki receives the guarded measurement.
        window.dispatchEvent(new CustomEvent('atelier:review-layout',{detail:{height:Math.ceil(outer.getBoundingClientRect().bottom)+4}}));
      },60);
    }
    function footer(){
      if(config.screen!=='review-bottom')return;
      const stock=stockFooter();
      if(stock){root.dataset.atelierToolbar='stock';root.dataset.atelierExtraCells=String(document.getElementById('innertable').tBodies[0].rows[0].cells.length>3);}else{delete root.dataset.atelierToolbar;delete root.dataset.atelierExtraCells;}
      const outer=document.getElementById('outer');
      if(outer!==observedOuter&&window.ResizeObserver){footerObserver?.disconnect();observedOuter=outer;if(outer){footerObserver=new ResizeObserver(()=>requestFooterFit());footerObserver.observe(outer);}}
      requestFooterFit();
    }
    function update(){
      scheduled=false;
      const enabled=config.style!=='off';
      if(!enabled){releaseGap();observeSize(null);delete root.dataset.atelierFit;delete root.dataset.atelierScreen;delete root.dataset.atelierCard;delete root.dataset.atelierToolbar;header?.remove();header=null;delete root.dataset.atelierContext;requestFooterFit();return;}
      root.dataset.atelierScreen=config.screen;root.dataset.atelierWorld=config.theme;root.dataset.atelierMotion=config.motion?'on':'off';root.dataset.atelierWidth=config.width;root.dataset.atelierAmbience=String(config.ambience!==false);root.dataset.atelierContext=['compact','full','hidden'].includes(config.context)?config.context:'compact';
      if(config.screen==='review-bottom'){footer();return;}
      if(config.screen!=='review')return;
      const reading=config.style==='adaptive'&&info.eligible===true&&!complexContent();
      root.dataset.atelierCard=reading?'reading':config.style==='adaptive'&&imageOcclusion()?'media':'native';
      if(reading&&config.context!=='hidden'){
        if(!header){
          header=document.createElement('div');header.id='atelier-review-header';
          const label=document.createElement('span');label.className='atelier-review-stage';
          const title=document.createElement('strong');title.className='atelier-review-lecture';
          const path=document.createElement('span');path.className='atelier-review-path';
          const toggle=document.createElement('button');toggle.type='button';toggle.className='atelier-review-details';
          toggle.textContent='Details';toggle.title='Show lecture path';toggle.setAttribute('aria-label','Show lecture path');toggle.setAttribute('aria-expanded','false');
          path.id='atelier-review-path';toggle.setAttribute('aria-controls',path.id);
          toggle.addEventListener('click',()=>{const open=header.dataset.expanded!=='true';header.dataset.expanded=String(open);toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'Less':'Details';scheduleLayout();});
          header.append(label,title,toggle,path);
          const qa=document.getElementById('qa');if(qa)qa.before(header);
        }
        const path=Array.isArray(info.path)?info.path.map(String):[];
        if(!header.isConnected){document.getElementById('qa')?.before(header);}
        header.querySelector('.atelier-review-stage').textContent=info.stage==='answer'?'REVEAL & REFLECT':'RECALL';
        header.querySelector('.atelier-review-lecture').textContent=path.at(-1)||'Your study session';
        header.querySelector('.atelier-review-path').textContent=path.slice(0,-1).join('  ›  ');
        header.querySelector('.atelier-review-path').title=path.join(' › ');
      }else{header?.remove();header=null;}
      if(reading){ownGap(document.getElementById('qa'));scheduleLayout();}
      else {resetQuestion=false;releaseGap();observeSize(null);delete root.dataset.atelierFit;}

    }
    const queue=()=>{if(!scheduled){scheduled=true;queueMicrotask(update);}};
    const api={painted:newPaint,settled(value){if(keyOf(value)===keyOf(info)){newPaint(value);scheduleLayout();}},measureFooter,refit:()=>requestFooterFit(true),setCard(value){newPaint(value);},configure(value){config={...config,...value};update();},diagnostics(){return {screen:root.dataset.atelierScreen||'off',card:root.dataset.atelierCard||'native',width:config.width,toolbar:root.dataset.atelierToolbar||'native',context:root.dataset.atelierContext||'original',layout:lastGeometry,version:config.version||'1.0.2',height:measureFooter()?.height||0,viewportHeight:innerHeight,scrollHeight:document.scrollingElement?.scrollHeight,fit:root.dataset.atelierFit||'native',headerClearance:root.style.getPropertyValue('--atelier-header-clearance'),bodyBackground:getComputedStyle(document.body).backgroundColor,controls:[...document.querySelectorAll('#outer button')].map(b=>{const r=b.getBoundingClientRect();return {command:b.getAttribute('onclick')?.match(/(?:ease[1-4]|ans|edit|more)/)?.[0]||'extension',x:r.x,y:r.y,width:r.width,height:r.height};})};}};
    window.AtelierReview=Object.freeze(api);
    const qa=document.getElementById('qa');
    if(qa){new MutationObserver(queue).observe(qa,{childList:true,subtree:true});new MutationObserver(scheduleLayout).observe(qa,{attributes:true,attributeFilter:['style']});}
    if(config.screen==='review-bottom'){
      new MutationObserver(queue).observe(document.body,{childList:true,subtree:true});
      window.addEventListener('resize',()=>requestFooterFit());
      document.fonts?.ready.then(()=>requestFooterFit(true));
    }
    if(config.screen==='review'){
      window.addEventListener('onigiri-reviewer-header-offset',queue);window.addEventListener('resize',queue);
      document.addEventListener('load',scheduleLayout,true);document.fonts?.ready.then(scheduleLayout);
      for(const name of ['wheel','touchmove','pointerdown'])window.addEventListener(name,()=>{userMoved=true;},{passive:true});
      window.addEventListener('keydown',e=>{if(['PageDown','PageUp','ArrowDown','ArrowUp','Home','End'].includes(e.key))userMoved=true;},true);
      window.addEventListener('pagehide',()=>{disposed=true;cancelAnimationFrame(alignFrame);qaSizeObserver?.disconnect();},{once:true});
    }
    update();
  };
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();

web/session-shell.css:
/* Session/results · rc5. Planner only; never styles native card contents. */
#es-app[data-suite="true"] .es-modal {
  width:min(960px,calc(100vw - 36px));max-width:calc(100vw - 36px);max-height:calc(100dvh - 36px);
  margin:auto;padding:0;border:1px solid var(--es-line);border-radius:22px;
  color:var(--es-text);background:var(--es-surface);overflow:hidden;
}
#es-app[data-suite="true"] .es-modal[data-view="results"] {width:min(1100px,calc(100vw - 36px));}
#es-app[data-suite="true"] .es-modal-inner {display:flex;flex-direction:column;max-height:calc(100dvh - 38px);min-height:0;padding:0;}
#es-app[data-suite="true"] .suite-modal-heading {display:flex;align-items:flex-start;gap:16px;justify-content:space-between;flex-shrink:0;padding:24px 28px 18px;border-bottom:1px solid var(--es-line);}
#es-app[data-suite="true"] .suite-modal-heading h2 {font:600 clamp(20px,2.1vw,28px)/1.2 var(--world-font,system-ui);letter-spacing:-.45px;margin:0;overflow-wrap:anywhere;}
#es-app[data-suite="true"] .suite-modal-close {font:24px/1 system-ui;width:36px;min-width:36px;height:36px;padding:0;border-radius:9px;}
#es-app[data-suite="true"] .suite-modal-scroll {flex:1 1 auto;min-height:0;overflow:auto;overscroll-behavior:contain;padding:24px 28px;scrollbar-width:thin;scrollbar-color:var(--es-line) transparent;}
#es-app[data-suite="true"] .es-modal .es-modal-actions {display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:flex-end;flex-shrink:0;margin:0;padding:16px 28px;border-top:1px solid var(--es-line);background:var(--es-surface);}
#es-app[data-suite="true"] .es-modal-actions button {font:500 13px/1.4 system-ui;min-height:40px;white-space:normal;}
#es-app[data-suite="true"] .suite-session-heading {display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px;font:12px/1.5 system-ui;color:var(--es-muted);margin-bottom:16px;}
#es-app[data-suite="true"] .suite-session-kicker {text-transform:uppercase;letter-spacing:1.1px;font-size:10px;font-weight:650;}
#es-app[data-suite="true"] .suite-result-hero {display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:28px;padding:26px;border:1px solid var(--es-line);border-radius:var(--world-radius,18px);background:linear-gradient(120deg,var(--es-soft),var(--es-surface));}
#es-app[data-suite="true"] .suite-result-hero .es-big-score {font:500 clamp(42px,7vw,68px)/1.1 var(--world-font,system-ui);letter-spacing:-2px;color:var(--es-text);margin:10px 0 12px;}
#es-app[data-suite="true"] .suite-result-hero .es-big-score small {font-size:.45em;margin-left:3px;letter-spacing:0;}
#es-app[data-suite="true"] .suite-result-hero p {font:12px/1.8 system-ui;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-result-metrics {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 18px;align-content:center;border-left:1px solid var(--es-line);padding-left:28px;}
#es-app[data-suite="true"] .suite-result-metrics div {display:flex;flex-direction:column;gap:6px;font-size:12px;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-result-metrics b {font:600 21px/1.2 system-ui;color:var(--es-text);}
#es-app[data-suite="true"] .suite-session-safety {display:flex;align-items:flex-start;gap:12px;margin:18px 0;padding:14px 16px;border:1px solid var(--es-line);border-left:3px solid var(--es-accent);border-radius:10px;background:var(--es-soft);color:var(--es-text);font:12px/1.65 system-ui;}
#es-app[data-suite="true"] .suite-session-safety svg {width:18px;height:18px;flex:0 0 18px;margin-top:2px;}
#es-app[data-suite="true"] .suite-session-safety strong {display:block;font-size:13px;}
#es-app[data-suite="true"] .suite-session-safety p {margin:4px 0 0;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-session-safety[data-kind="learning"] {border-left-width:5px;outline:1px solid var(--es-line);}
#es-app[data-suite="true"] .es-result-diagnostics {background:none;border:0;padding:0 0 20px;margin:0;color:var(--es-text);}
#es-app[data-suite="true"] .es-result-diagnostics h3, #es-app[data-suite="true"] .suite-result-breakdown h3, #es-app[data-suite="true"] .suite-result-title h3 {font:600 16px/1.4 system-ui;margin:0 0 8px;}
#es-app[data-suite="true"] .es-result-diagnostics p {font:13px/1.7 system-ui;color:var(--es-muted);margin:0;}
#es-app[data-suite="true"] .suite-result-breakdown {margin:4px 0 22px;}
#es-app[data-suite="true"] .suite-result-deck {display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:18px;padding:12px 0;border-bottom:1px solid var(--es-line);font:13px/1.6 system-ui;}
#es-app[data-suite="true"] .suite-result-deck span {overflow-wrap:anywhere;}
#es-app[data-suite="true"] .suite-result-deck small {color:var(--es-muted);}
#es-app[data-suite="true"] .suite-result-title {display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;}
#es-app[data-suite="true"] .suite-result-title label {display:flex;gap:8px;align-items:center;font:12px/1.4 system-ui;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-result-title select {width:auto;max-width:210px;min-height:36px;}
#es-app[data-suite="true"] .suite-result-detail-note {font-size:12px;color:var(--es-muted);margin:0 0 14px;}
#es-app[data-suite="true"] .suite-result-table {border:1px solid var(--es-line);border-radius:12px;overflow:hidden;font:12px/1.5 system-ui;}
#es-app[data-suite="true"] .suite-result-table [role="row"] {display:grid;grid-template-columns:75px 1.1fr 1.3fr 1.2fr;gap:14px;padding:12px 15px;border-bottom:1px solid var(--es-line);}
#es-app[data-suite="true"] .suite-result-table [role="row"]:last-child {border:0;}
#es-app[data-suite="true"] .suite-result-table small {display:block;color:var(--es-muted);font-size:10px;margin-top:3px;}
#es-app[data-suite="true"] .suite-result-table [role="cell"] {min-width:0;overflow-wrap:anywhere;}
#es-app[data-suite="true"] .suite-result-table-head {background:var(--es-soft);font-weight:600;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-result-pagination {display:flex;gap:12px;flex-wrap:wrap;justify-content:space-between;align-items:center;margin-top:12px;font:12px/1.6 system-ui;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-result-pagination>div {display:flex;gap:6px;}
#es-app[data-suite="true"] .suite-session-empty {padding:24px;border:1px dashed var(--es-line);border-radius:12px;color:var(--es-muted);font:13px/1.7 system-ui;}
#es-app[data-suite="true"] .suite-result-method {margin-top:24px;padding:14px 16px;background:var(--es-soft);border-radius:10px;font:12px/1.75 system-ui;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-result-method summary {cursor:pointer;font-weight:600;color:var(--es-text);}
#es-app[data-suite="true"] .suite-result-method p {margin:12px 0 0;}
#es-app[data-suite="true"] .suite-pip-intro {display:flex;gap:20px;align-items:center;}
#es-app[data-suite="true"] .suite-pip-avatar {flex:0 0 100px;background:linear-gradient(180deg,var(--es-soft),var(--es-surface));border:1px solid var(--es-line);border-radius:20px;padding:18px;}
#es-app[data-suite="true"] .suite-pip-avatar img {width:64px;height:80px;object-fit:contain;}
#es-app[data-suite="true"] .suite-pip-intro h3 {font:500 25px/1.3 var(--world-font,system-ui);margin:7px 0 10px;color:var(--es-text);}
#es-app[data-suite="true"] .suite-pip-intro p {font:13px/1.7 system-ui;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-pip-count {margin-top:24px;}
#es-app[data-suite="true"] .suite-pip-count input {max-width:180px;}
#es-app[data-suite="true"] .suite-pip-choice {padding:18px;border:1px solid var(--es-line);border-radius:12px;align-items:flex-start;}
#es-app[data-suite="true"] .suite-pip-choice input {flex-shrink:0;margin-top:3px;}
#es-app[data-suite="true"] .suite-resume-card {display:flex;gap:18px;align-items:center;padding:20px 22px;border:1px solid var(--es-line);border-radius:var(--world-radius,16px);background:var(--es-soft);margin:0 0 22px;}
#es-app[data-suite="true"] .suite-resume-card>div:nth-child(2) {flex:1;min-width:0;}
#es-app[data-suite="true"] .suite-resume-card h3 {font:600 16px/1.5 system-ui;margin:6px 0;color:var(--es-text);}
#es-app[data-suite="true"] .suite-resume-card small {display:block;font:11px/1.6 system-ui;color:var(--es-muted);margin-top:8px;}
#es-app[data-suite="true"] .suite-resume-symbol {width:38px;height:38px;display:grid;place-items:center;flex-shrink:0;background:var(--es-surface);border-radius:10px;}
#es-app[data-suite="true"] .suite-resume-symbol svg {width:20px;height:20px;}
#es-app[data-suite="true"] .es-history-row {gap:18px;padding:16px;border:1px solid var(--es-line);border-radius:12px;background:var(--es-surface);margin-top:8px;}
#es-app[data-suite="true"] .es-history-row>div {flex:1;min-width:0;font:12px/1.6 system-ui;}
#es-app[data-suite="true"] .es-history-row p {margin:3px 0 0;}
#es-app[data-suite="true"] .es-history-row .es-score {font:500 24px/1.2 var(--world-font,system-ui);color:var(--es-accent);}
#es-app[data-suite="true"] .es-companion-panel .pip-card {border-radius:var(--world-radius,20px) var(--world-radius,20px) 0 0;}
#es-app[data-suite="true"] .es-modal :focus-visible {outline:2px solid var(--es-accent);outline-offset:3px;}
@media(max-width:650px){
 #es-app[data-suite="true"] .es-modal,#es-app[data-suite="true"] .es-modal[data-view="results"] {width:calc(100vw - 16px);max-width:calc(100vw - 16px);max-height:calc(100dvh - 16px);border-radius:14px;}
 #es-app[data-suite="true"] .es-modal-inner {max-height:calc(100dvh - 18px);}
 #es-app[data-suite="true"] .suite-modal-heading {padding:16px;gap:8px;}
 #es-app[data-suite="true"] .suite-modal-scroll {padding:16px;}
 #es-app[data-suite="true"] .es-modal .es-modal-actions {padding:12px;gap:6px;}
 #es-app[data-suite="true"] .es-modal-actions button {min-height:36px;font-size:12px;padding:8px 10px;flex:1 1 auto;}
 #es-app[data-suite="true"] .suite-result-hero {grid-template-columns:1fr;padding:18px;gap:20px;}
 #es-app[data-suite="true"] .suite-result-metrics {border-left:0;border-top:1px solid var(--es-line);padding-left:0;padding-top:18px;}
 #es-app[data-suite="true"] .suite-result-deck {gap:10px;grid-template-columns:minmax(0,1fr) auto;}
 #es-app[data-suite="true"] .suite-result-deck small {grid-column:1/-1;}
 #es-app[data-suite="true"] .suite-result-table [role="row"] {grid-template-columns:42px .95fr 1.1fr;gap:8px;padding:10px;}
 #es-app[data-suite="true"] .suite-result-table [role="row"]>:last-child {grid-column:2/-1;}
 #es-app[data-suite="true"] .suite-result-table-head>:last-child {display:none;}
 #es-app[data-suite="true"] .suite-pip-avatar {flex-basis:72px;padding:9px;}
 #es-app[data-suite="true"] .suite-pip-avatar img {width:52px;height:70px;}
 #es-app[data-suite="true"] .suite-pip-intro {gap:12px;align-items:flex-start;}
 #es-app[data-suite="true"] .suite-pip-intro h3 {font-size:21px;}
 #es-app[data-suite="true"] .suite-resume-card {flex-wrap:wrap;padding:16px;gap:12px;}
 #es-app[data-suite="true"] .suite-resume-card>.es-flex {margin-left:auto;}
}
@media(forced-colors:active){#es-app[data-suite="true"] .suite-session-safety,#es-app[data-suite="true"] .es-modal {border:1px solid CanvasText;}}
@media(prefers-reduced-motion:reduce){#es-app[data-suite="true"] .es-modal *{transition:none!important;animation:none!important;}}

#es-app[data-suite="true"] .suite-modal-alerts {flex-shrink:0;padding:0 18px;}
#es-app[data-suite="true"] .suite-modal-alerts .es-toast {position:static;transform:none;width:auto;max-width:100%;margin:12px 0 0;box-sizing:border-box;}

web/shared.css:
/* Atelier Shared Home 0.7.1. Applied ONLY to the DeckBrowser document.
   Presentation adapters for known Onigiri surfaces; game canvases, SVG artwork,
   images, widget scripts, hidden state, and stored Onigiri settings are untouched. */
html[data-atelier-shared="true"],
html[data-atelier-shared="true"] body,
html[data-atelier-shared="true"] .modern-main-menu {
  --canvas:var(--ats-bg)!important; --canvas-inset:var(--ats-panel)!important;
  --canvas-elevated:var(--ats-raised)!important; --canvas-overlay:var(--ats-panel)!important;
  --fg:var(--ats-text)!important; --fg-default:var(--ats-text)!important;
  --fg-subtle:var(--ats-muted)!important; --fg-muted:var(--ats-muted)!important;
  --border:var(--ats-line)!important; --border-subtle:var(--ats-line-soft)!important;
  --link:var(--ats-accent)!important; --accent-color:var(--ats-accent)!important;
  --icon-color:var(--ats-accent)!important; --button-bg:var(--ats-raised)!important;
  --font-main: -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif!important;
  --font-small-title:var(--font-main)!important; --font-big-title:var(--font-main)!important;
  --font-deck:var(--font-main)!important; --font-body:var(--font-main)!important;
  --font-stats:var(--font-main)!important;
  color-scheme:var(--ats-scheme)!important;
  background:var(--ats-bg)!important; color:var(--ats-text)!important;
  font-family:var(--font-main)!important;
}
html[data-atelier-shared="true"] body { text-shadow:none!important; }
html[data-atelier-shared="true"] .modern-main-menu { box-sizing:border-box!important; gap:24px!important; }
html[data-atelier-shared="true"] .modern-main-menu .main-content {
  min-width:0!important; background:transparent!important; color:var(--ats-text)!important;
  box-sizing:border-box!important; padding-bottom:28px!important;
}
html[data-atelier-shared="true"] .modern-main-menu .injected-stats-block {min-width:0!important;max-width:100%!important;width:100%!important;}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left {
  background:var(--ats-side)!important; color:var(--ats-text)!important;
  border:1px solid var(--ats-line)!important; border-radius:20px!important;
  box-shadow:0 8px 32px #0000000b!important; backdrop-filter:none!important;
}
html[data-atelier-shared="true"] .modern-main-menu:not(.onigiri-sidebar-center):not(.onigiri-cycle-stacked) > .sidebar-left:not(.collapsed):not(.sidebar-collapsed) {
  max-width:min(420px,40vw)!important;
}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-expanded-content { background:transparent!important;min-height:0!important; }
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left :is(h1,h2,h3,.welcome-text,.welcome-message,.profile-name,.opro-name) {
  color:var(--ats-text)!important;font-family:var(--font-main)!important;text-shadow:none!important;
}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left :is(.menu-item,.add-button-dashed,.menu-group summary) {
  color:var(--ats-muted)!important; font-family:var(--font-main)!important; font-size:14px!important;
  line-height:1.5!important; border-radius:10px!important;
}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left :is(.menu-item,.add-button-dashed,.menu-group summary):hover {background:var(--ats-hover)!important;color:var(--ats-text)!important;}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left .add-button-dashed,
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left .action-add {border-color:var(--ats-line)!important;}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left .profile-bar {background:var(--ats-raised)!important;border:1px solid var(--ats-line)!important;border-radius:16px!important;}
html[data-atelier-shared="true"] .modern-main-menu .profile-bg-layer {opacity:.12!important;}
html[data-atelier-shared="true"] .modern-main-menu :is(.rl-chip-level,.restaurant-level-chip) {color:var(--ats-text)!important;font-family:var(--font-main)!important;}
html[data-atelier-shared="true"] .modern-main-menu .deck-table {width:100%!important;table-layout:fixed!important;border-spacing:0 3px!important;}
html[data-atelier-shared="true"] .modern-main-menu .decktd {min-width:0!important;gap:4px!important;}
html[data-atelier-shared="true"] .modern-main-menu a.deck {
  font:500 13px/1.5 var(--font-main)!important; color:var(--ats-text)!important;
  min-width:0!important;overflow:hidden!important;overflow-wrap:anywhere!important;
  text-overflow:ellipsis!important;white-space:normal!important; padding:8px 5px!important;
}
html[data-atelier-shared="true"] .modern-main-menu tr.deck:hover {background:var(--ats-hover)!important;}
html[data-atelier-shared="true"] .modern-main-menu tr:is(.selected,.current,.deck-selected) {background:var(--ats-accent-soft)!important;}
html[data-atelier-shared="true"] .modern-main-menu :is(.collapse,.deck-collapse,.decktd .collapse) {color:var(--ats-muted)!important;}
html[data-atelier-shared="true"] .modern-main-menu :is(.onigiri-widget-title,.main-content h1) {
  color:var(--ats-text)!important;font-family:var(--font-main)!important;
  font-size:clamp(22px,2vw,30px)!important;line-height:1.3!important;letter-spacing:-.7px!important;
}
html[data-atelier-shared="true"] .modern-main-menu :is(.stat-card,.onigiri-restaurant-level-widget,.onigiri-favorites-widget,#onigiri-heatmap-container,.prep-station-widget,.hashi-notes-widget,.onigimon-widget,.hex-land-widget) {
  background:var(--ats-panel)!important;color:var(--ats-text)!important;
  border:1px solid var(--ats-line)!important;border-radius:18px!important;
  box-shadow:0 4px 18px #00000008!important;
}
html[data-atelier-shared="true"] .modern-main-menu :is(.stat-card h3,.onigiri-widget-head h3,.restaurant-info h3,.restaurant-info .level-label) {
  color:var(--ats-muted)!important;font:600 12px/1.45 var(--font-main)!important;
  letter-spacing:.65px!important;text-transform:uppercase!important;
}
html[data-atelier-shared="true"] .modern-main-menu :is(.stat-value,.restaurant-level,.restaurant-level-number,.level-number,.level-value) {
  color:var(--ats-text)!important;font-family:var(--font-main)!important;
  line-height:1.25!important;letter-spacing:-.75px!important;font-variant-numeric:tabular-nums;
}
html[data-atelier-shared="true"] .modern-main-menu .stat-value {font-size:clamp(22px,2.8vw,34px)!important;}
html[data-atelier-shared="true"] .modern-main-menu :is(.stat-unit,.restaurant-info,.restaurant-info p,.restaurant-info span,.favorites-placeholder,.favorites-list a) {
  font-family:var(--font-main)!important;color:var(--ats-muted)!important;text-shadow:none!important;
}
html[data-atelier-shared="true"] .modern-main-menu :is(.star-rating,.stat-icon-chip) {color:var(--ats-accent)!important;}
html[data-atelier-shared="true"] .modern-main-menu :is(.favorites-list a:hover,.onigiri-favorite-item:hover) {background:var(--ats-hover)!important;color:var(--ats-text)!important;}
html[data-atelier-shared="true"] .modern-main-menu :is(#deck-list-container,.main-content,.sidebar-left) {scrollbar-color:var(--ats-line) transparent;scrollbar-width:thin;}
html[data-atelier-shared="true"] .modern-main-menu :is(input,textarea,select):not([type="color"]):not([type="checkbox"]):not([type="range"]) {
  color:var(--ats-text);border-color:var(--ats-line);background-color:var(--ats-panel);
}
/* All original widget nodes stay where their owning add-on put them.
   Unknown content keeps its typography/artwork. Only its outer clipping is fixed. */
html[data-atelier-shared="true"] .modern-main-menu .external-widget-container {
  min-width:0!important;max-width:100%!important;box-sizing:border-box!important;
  scrollbar-width:thin;scrollbar-color:var(--ats-line) transparent;
}
html[data-atelier-shared="true"] .modern-main-menu .unified-grid {max-width:100%!important;}
html[data-atelier-shared="true"] .modern-main-menu .unified-grid[data-atelier-grid-columns] {
  grid-template-columns:repeat(var(--ats-grid-columns),minmax(0,1fr))!important;
}
html[data-atelier-shared="true"] .modern-main-menu .unified-grid[data-atelier-grid-compact="true"] {
  grid-template-rows:none!important;grid-auto-rows:minmax(140px,auto)!important;align-items:stretch!important;
}
html[data-atelier-shared="true"] .modern-main-menu .unified-grid[data-atelier-grid-compact="true"] > :is(.onigiri-widget-container,.external-widget-container) {
  grid-row:auto!important;grid-column:span var(--ats-widget-span,1)!important;
  min-width:0!important;min-height:0!important;height:auto!important;
}
html[data-atelier-shared="true"] .modern-main-menu .unified-grid[data-atelier-grid-compact="true"] > [data-atelier-widget-title] {grid-column:1 / -1!important;}
/* Sprout is a real responsive widget, not a sliver in a one-column tile. */
html[data-atelier-home] .external-widget-container[data-atelier-sprout-wrap] {
  grid-column:1 / -1!important;grid-row:auto!important;align-self:start!important;
  width:100%!important;max-width:100%!important;min-width:0!important;
  height:auto!important;min-height:0!important;max-height:none!important;
  overflow:visible!important;contain:none!important;box-sizing:border-box!important;
}
html[data-atelier-home] .external-widget-container[data-atelier-sprout-wrap="empty"] {display:none!important;}
html[data-atelier-home] #es-countdowns {
  width:100%!important;max-width:100%!important;min-width:0!important;box-sizing:border-box!important;
  margin:0!important;padding:0!important;display:grid!important;
  grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr))!important;
  align-items:stretch!important;justify-content:stretch!important;gap:12px!important;
  font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif!important;
  text-align:left!important;container-type:inline-size;
}
html[data-atelier-home] #es-countdowns .es-chip {
  display:grid!important;grid-template-columns:36px minmax(0,1fr) auto 16px!important;
  align-items:center!important;gap:12px!important;width:100%!important;
  max-width:100%!important;min-width:0!important;height:auto!important;min-height:78px!important;
  padding:14px!important;border-radius:16px!important;overflow:visible!important;
  font:inherit!important;line-height:1.4!important;text-shadow:none!important;
  transform:none!important;box-shadow:none!important;letter-spacing:normal!important;
}
html[data-atelier-home] #es-countdowns .es-chip-copy {min-width:0!important;}
html[data-atelier-home] #es-countdowns .es-chip-title {font:600 14px/1.4 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif!important;white-space:normal!important;overflow-wrap:anywhere!important;}
html[data-atelier-home] #es-countdowns .es-chip-sub {font-size:11px!important;white-space:normal!important;overflow-wrap:anywhere!important;opacity:1!important;}
html[data-atelier-home] #es-countdowns .es-time {font-size:13px!important;margin:0!important;padding:8px!important;}
html[data-atelier-home] #es-countdowns .es-chip-empty .es-plus {grid-column:3!important;}
html[data-atelier-home] #es-countdowns .es-mark {background:var(--es-tint)!important;}
html[data-atelier-home][data-atelier-match-sprout="true"] #es-countdowns {
  --es-accent:var(--ats-accent)!important;--es-tint:var(--ats-panel)!important;
  --es-chip-line:var(--ats-line)!important;color:var(--ats-text)!important;
}
html[data-atelier-home][data-atelier-match-sprout="true"] #es-countdowns .es-chip {
  background:var(--ats-panel)!important;color:var(--ats-text)!important;border:1px solid var(--ats-line)!important;
}
html[data-atelier-home][data-atelier-match-sprout="true"] #es-countdowns .es-chip:hover {background:var(--ats-raised)!important;border-color:var(--ats-accent)!important;}
html[data-atelier-home][data-atelier-match-sprout="true"] #es-countdowns .es-chip-sub {color:var(--ats-muted)!important;}
html[data-atelier-home][data-atelier-match-sprout="true"] #es-countdowns .es-time {background:var(--ats-accent-soft)!important;color:var(--ats-accent)!important;}
html[data-atelier-home] #es-countdowns .es-chip:focus-visible {outline:2px solid var(--es-accent)!important;outline-offset:3px!important;}
@container (max-width:300px) {
  html[data-atelier-home] #es-countdowns .es-chip {grid-template-columns:32px minmax(0,1fr)!important;gap:8px!important;}
  html[data-atelier-home] #es-countdowns .es-time {grid-column:2!important;justify-self:start!important;}
  html[data-atelier-home] #es-countdowns .es-chip-arrow {display:none!important;}
}
@media(max-width:700px) {
  html[data-atelier-shared="true"] .modern-main-menu {flex-direction:column!important;height:auto!important;min-height:100vh!important;padding:12px!important;gap:16px!important;}
  html[data-atelier-shared="true"] .modern-main-menu > .sidebar-left:not(.collapsed):not(.sidebar-collapsed) {width:100%!important;max-width:none!important;min-width:0!important;max-height:320px!important;}
  html[data-atelier-shared="true"] .modern-main-menu .main-content {width:100%!important;overflow:visible!important;margin:0!important;padding:0 0 24px!important;}
  html[data-atelier-shared="true"] body {overflow-y:auto!important;overflow-x:hidden!important;}
}
@media(prefers-reduced-motion:reduce) {
  html[data-atelier-home] #es-countdowns .es-chip,html[data-atelier-home] #es-countdowns .es-chip-arrow {transition:none!important;transform:none!important;}
}
html[data-atelier-home][data-atelier-shared] .modern-main-menu .unified-grid > .external-widget-container[data-atelier-sprout-wrap] {
  grid-column:1 / -1!important;grid-row:auto!important;height:auto!important;min-height:0!important;max-height:none!important;overflow:visible!important;
}
/* Small native controls remain compact, but not olive on a different theme. */
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left :is(.sidebar-top-buttons button,.sidebar-top-actions button,.deck-header-btn,.deck-focus-btn) {
  background-color:var(--ats-raised)!important;color:var(--ats-accent)!important;border-color:var(--ats-line)!important;
}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left :is(.sidebar-top-buttons button,.sidebar-top-actions button,.deck-header-btn,.deck-focus-btn):hover {
  background-color:var(--ats-hover)!important;
}
html[data-atelier-shared="true"] .modern-main-menu :is(.rl-chip-level,.restaurant-level-chip) {background-color:var(--ats-accent-soft)!important;color:var(--ats-accent)!important;}
html[data-atelier-shared="true"] .modern-main-menu .sidebar-left :is(.folder-icon,.sidebar-menu a) {color:var(--ats-muted)!important;font-family:var(--font-main)!important;}
html[data-atelier-shared="true"] .modern-main-menu :is(.hashi-notes-widget h3,.onigiri-favorites-widget h3) {color:var(--ats-muted)!important;font:600 12px/1.5 var(--font-main)!important;letter-spacing:.65px!important;}

/* Preserve themed game art when Onigiri intentionally expands its building. */
html[data-atelier-shared="true"] .modern-main-menu .onigiri-restaurant-level-widget.expanded-view {background:var(--theme-bg,var(--ats-panel))!important;}
/* Atelier owns the interface. Onigiri's widget DOM/game remains original,
   but its redundant folder navigation does not compete with the organizer. */
html[data-atelier-owner="atelier"][data-atelier-shared="true"] body,
html[data-atelier-owner="atelier"][data-atelier-shared="true"] .modern-main-menu{background:var(--ats-bg)!important;color:var(--ats-text)!important;}
html[data-atelier-owner="atelier"] .modern-main-menu>.sidebar-left,
html[data-atelier-owner="atelier"] .modern-main-menu>.resize-handle,
html[data-atelier-owner="atelier"] #onigiri-sidebar-edge-pill{display:none!important;}
html[data-atelier-owner="atelier"] .modern-main-menu>.main-content{width:100%!important;max-width:1500px!important;margin:0 auto!important;padding:24px 32px 40px!important;overflow:auto!important;}
html[data-atelier-owner="atelier"] .modern-main-menu{gap:0!important;}
html[data-atelier-owner="atelier"] .modern-main-menu .onigiri-widget-title{font-size:22px!important;}
html[data-atelier-owner="atelier"] .modern-main-menu .stat-card{background:linear-gradient(140deg,var(--ats-panel),var(--ats-hero-end))!important;border-radius:20px!important;}
html[data-atelier-owner="atelier"] .modern-main-menu :is(.rl-chip-level,.restaurant-level-chip){background:var(--ats-accent-soft)!important;color:var(--ats-accent-strong)!important;}
html[data-atelier-home][data-atelier-match-sprout="true"] #es-countdowns .es-chip{background:linear-gradient(120deg,var(--ats-panel),var(--ats-hero-end))!important;border-radius:17px!important;min-height:66px!important;}
html[data-atelier-home][data-atelier-match-sprout="true"] #es-countdowns .es-time{background:var(--ats-accent-soft)!important;color:var(--ats-accent-strong)!important;}
@media(max-width:700px){html[data-atelier-owner="atelier"] .modern-main-menu>.main-content{padding:12px!important;}}

/* Balanced widget layout only when Atelier owns the page. Original nodes stay in place. */
html[data-atelier-owner="atelier"] .modern-main-menu>.main-content{max-width:1360px!important;padding:22px 28px 40px!important;}
html[data-atelier-owner="atelier"] .modern-main-menu .main-content>h1,html[data-atelier-owner="atelier"] .onigiri-widget-title{margin:18px 0 14px!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]{grid-template-columns:repeat(var(--ats-grid-columns),minmax(0,1fr))!important;grid-auto-rows:minmax(150px,auto)!important;gap:16px!important;align-items:stretch!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]>:is(.onigiri-widget-container,.external-widget-container){grid-column:span 1!important;grid-row:auto!important;height:auto!important;min-height:0!important;max-height:none!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]>[data-atelier-widget-title],html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]>.external-widget-container{grid-column:1 / -1!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced="4"]>[data-atelier-building]{grid-column:span 2!important;grid-row:span 2!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced="2"]>[data-atelier-building]{grid-column:1 / -1!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .stat-card{min-height:150px!important;height:100%!important;padding:22px!important;box-sizing:border-box!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view){min-height:280px!important;max-height:none!important;height:100%!important;box-sizing:border-box!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view) img{max-height:300px;object-fit:contain;}
@media(max-width:700px){html[data-atelier-owner="atelier"] .modern-main-menu>.main-content{padding:14px!important;}html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .stat-card{padding:18px!important;min-height:130px!important;}}

/* Compact, content-first rewards room. Provider containers stay live and intact. */
html[data-atelier-owner="atelier"] .modern-main-menu .injected-stats-block{box-sizing:border-box!important;min-width:0!important;max-width:100%!important;align-items:stretch!important;gap:0!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]{grid-auto-rows:minmax(114px,auto)!important;gap:14px!important;grid-auto-flow:row dense!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]>[data-atelier-building]{order:0!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]>[data-atelier-metric]{order:1!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]>[data-atelier-widget-title]{order:-1!important;min-height:0!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced]>.external-widget-container{order:5!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .stat-card{min-height:114px!important;padding:16px!important;border-radius:16px!important;gap:10px!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .stat-card .stat-value{font-size:26px!important;line-height:1.2!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view){display:grid!important;grid-template-columns:minmax(100px,42%) minmax(0,1fr)!important;align-items:center!important;gap:18px!important;padding:20px!important;min-height:242px!important;border-radius:18px!important;overflow:visible!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view) .restaurant-image-container{width:100%!important;max-width:200px!important;min-width:0!important;height:auto!important;max-height:185px!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view) img{width:100%!important;height:auto!important;max-height:185px!important;object-fit:contain!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view) .restaurant-info{width:auto!important;min-width:0!important;}
html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view) :is(.level-number,.restaurant-level-number,.level-value){font-size:36px!important;}
html[data-atelier-owner="atelier"] .modern-main-menu .injected-stats-block>h1{font-size:22px!important;margin:8px 0 14px!important;line-height:1.25!important;}
@media(max-width:600px){html[data-atelier-owner="atelier"] .unified-grid[data-atelier-balanced] .onigiri-restaurant-level-widget:not(.expanded-view){padding:16px!important;gap:12px!important;min-height:215px!important;}}
/* Beat the legacy responsive grid rule, not the widget's own interactive content. */
html[data-atelier-owner="atelier"] .modern-main-menu .unified-grid[data-atelier-balanced="4"][data-atelier-grid-compact]>.onigiri-widget-container[data-atelier-building]{grid-column:span 2!important;grid-row:span 2!important;align-self:stretch!important;}
html[data-atelier-owner="atelier"] .modern-main-menu .unified-grid[data-atelier-balanced="2"][data-atelier-grid-compact]>.onigiri-widget-container[data-atelier-building],html[data-atelier-owner="atelier"] .modern-main-menu .unified-grid[data-atelier-balanced="1"][data-atelier-grid-compact]>.onigiri-widget-container[data-atelier-building]{grid-column:1/-1!important;grid-row:auto!important;}
html[data-atelier-owner="atelier"] .modern-main-menu .unified-grid[data-atelier-balanced][data-atelier-grid-compact]>.external-widget-container{grid-column:1/-1!important;grid-row:auto!important;}
/* Let title/utility rows size to their content; only the metrics have a minimum. */
html[data-atelier-owner="atelier"] .modern-main-menu .unified-grid[data-atelier-balanced][data-atelier-grid-compact]{grid-auto-rows:minmax(0,auto)!important;}

web/studio-home.css:
/* Shared control rhythm for the accepted home. Library/navigation logic unchanged.
   Shadow-scoped: no Onigiri, card or external-window selectors. */
:host {--studio-control:40px;}
.unified-topbar .top-actions {align-items:center;gap:8px;}
.unified-topbar [data-command] {min-height:var(--studio-control);border-radius:10px;padding:9px 13px;display:inline-flex;align-items:center;gap:8px;font-size:13px;line-height:1.35;}
.unified-topbar .search {min-height:40px;border-radius:10px;}
.unified-topbar .icon-button {width:38px;height:38px;border-radius:10px;}
.unified-topbar :is(button,input) {box-shadow:none;}
:host([data-motion="false"]) .unified-topbar * {transition:none!important;}
@media(max-width:740px) {.unified-topbar [data-command]{font-size:12px;padding:8px 10px;min-height:38px;gap:6px;}}
@media(max-width:480px) {.unified-topbar [data-command]{font-size:11px;padding:8px 7px;}}
@media(prefers-reduced-motion:reduce){.unified-topbar *{transition:none!important;transform:none!important;}}

web/studio-shell.css:
/* Atelier Studio shell · rc3
   Layout for the bundled planner only. The assessment engine, card Previewer,
   practice runner and original standalone stylesheet are deliberately untouched.
   Header rows occupy real layout space; only the content/rail scroll. */
html.es-host:has(#es-app[data-suite="true"]),
html.es-host:has(#es-app[data-suite="true"]) body {height:100%;margin:0;padding:0;overflow:hidden;}
#es-app[data-suite="true"] {
  --studio-control:40px; --studio-radius:18px; --studio-gutter:clamp(20px,2.4vw,34px);
  height:100vh;height:100dvh;min-height:0;max-width:100%;display:grid;
  grid-template-rows:auto minmax(0,1fr);overflow:hidden;isolation:isolate;
  font:14px/1.55 "Segoe UI",-apple-system,BlinkMacSystemFont,Arial,sans-serif;
}
#es-app[data-suite="true"] :is(button,input,select,textarea){box-sizing:border-box;}
#es-app[data-suite="true"] button {touch-action:manipulation;}
#es-app[data-suite="true"] button:active {transform:none;}
html #es-app[data-suite="true"] .es-app-header {
  display:grid!important;grid-template-columns:minmax(180px,1fr) auto auto;
  grid-template-areas:"brand tools world" "nav nav nav";align-items:center;
  position:relative!important;inset:auto!important;height:auto!important;min-height:0!important;
  max-height:none!important;padding:12px 24px 0!important;gap:10px 18px!important;
  background:var(--es-surface);border-bottom:1px solid var(--es-line);z-index:8;
  width:100%;flex-shrink:0;box-shadow:none;
}
#es-app[data-suite="true"] .es-brand {grid-area:brand;min-width:0;gap:10px;font-size:23px;align-items:center;}
#es-app[data-suite="true"] .es-brand::after {display:none!important;}
#es-app[data-suite="true"] .es-brand-mark {width:32px;height:34px;flex:0 0 32px;background:transparent;border:0;box-shadow:none;}
#es-app[data-suite="true"] .es-brand-mark img {width:32px;height:34px;object-fit:contain;}
#es-app[data-suite="true"] .suite-brand-copy {display:flex;align-items:baseline;gap:14px;min-width:0;}
#es-app[data-suite="true"] .suite-brand-copy>strong {font-size:23px;letter-spacing:-1px;line-height:1.2;}
#es-app[data-suite="true"] .es-header-note {display:block!important;font:12px/1.4 "Segoe UI",system-ui,sans-serif;letter-spacing:.05px;white-space:nowrap;padding:0;margin:0;border:0;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-tool-links {grid-area:tools;display:flex;align-items:center;gap:6px;flex-wrap:nowrap;margin:0;}
#es-app[data-suite="true"] .suite-tool-links button {
  min-height:var(--studio-control);font:500 13px/1.35 "Segoe UI",system-ui,sans-serif;
  padding:9px 13px;display:inline-flex;align-items:center;justify-content:center;gap:8px;
  white-space:nowrap;border-radius:10px;background:var(--es-surface);color:var(--es-text);border:1px solid var(--es-line);
}
#es-app[data-suite="true"] .suite-tool-links button:first-child {background:var(--es-soft);border-color:var(--es-line);color:var(--es-accent);}
#es-app[data-suite="true"] .suite-tool-links svg {width:17px;height:17px;}
html #es-app[data-suite="true"] .suite-world-switch {grid-area:world;display:flex;gap:8px;margin:0;order:0;font-size:11px;color:var(--es-muted);position:relative;width:auto;}
#es-app[data-suite="true"] .suite-world-switch select {width:136px;max-width:136px;min-height:40px;padding:8px 10px;font-size:13px;line-height:1.4;}
#es-app[data-suite="true"] .suite-world-error {position:absolute;top:calc(100% + 8px);right:0;min-width:220px;max-width:300px;padding:12px;background:var(--es-surface);border:1px solid var(--es-danger);border-radius:10px;color:var(--es-text);z-index:12;box-shadow:0 8px 24px #0003;}
html #es-app[data-suite="true"] .es-top-nav {
  grid-area:nav;min-width:0;display:flex;flex-wrap:nowrap!important;align-items:stretch;
  gap:6px;background:transparent;border:0;border-top:1px solid var(--es-line);
  border-radius:0;padding:6px 0;box-shadow:none;width:100%;
}
#es-app[data-suite="true"] .es-top-nav button {
  display:inline-flex;gap:8px;align-items:center;justify-content:center;min-height:38px;
  font-size:13px;padding:8px 15px;line-height:1.3;white-space:nowrap;
  border-radius:9px;background:transparent;border:1px solid transparent;
}
#es-app[data-suite="true"] .es-top-nav button[aria-current="page"] {background:var(--es-soft);color:var(--es-accent);}
#es-app[data-suite="true"] .es-top-nav button svg {width:17px;height:17px;display:block;}
#es-app[data-suite="true"] .es-top-nav .suite-home-link {margin-left:auto;color:var(--es-muted);}
#es-app[data-suite="true"] .es-top-nav .suite-home-link svg {transform:rotate(180deg);}
#es-app[data-suite="true"] .es-layout {display:grid;grid-template-columns:208px minmax(0,1fr);min-height:0;height:100%;overflow:hidden;position:relative;}
#es-app[data-suite="true"] .suite-exams-toggle {display:none;}
html #es-app[data-suite="true"] .es-sidebar {padding:24px 14px 18px;gap:14px;width:auto;min-height:0;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;scrollbar-gutter:stable;scrollbar-width:thin;scrollbar-color:var(--es-line) transparent;}
#es-app[data-suite="true"] .es-sidebar-label {padding:0 8px;}
#es-app[data-suite="true"] .es-sidebar-label .es-label {letter-spacing:1.3px;font-size:10px;}
#es-app[data-suite="true"] .es-exam-list {min-height:0;gap:8px;flex:none;}
#es-app[data-suite="true"] .es-exam-link {display:flex;gap:10px;align-items:flex-start;min-width:0;padding:12px 10px;min-height:62px;border-radius:12px;flex-shrink:0;}
#es-app[data-suite="true"] .es-exam-link>.es-exam-stamp {display:flex;flex-direction:column;justify-content:center;width:34px;min-width:34px;height:44px;border-radius:8px;font-size:18px;line-height:1.25;padding:5px;}
#es-app[data-suite="true"] .es-exam-link>.es-exam-stamp small {font-size:9px;}
#es-app[data-suite="true"] .es-exam-link-copy {display:block;min-width:0;flex:1;}
#es-app[data-suite="true"] .es-exam-link strong {font-size:12px;line-height:1.45;font-weight:600;overflow-wrap:anywhere;}
#es-app[data-suite="true"] .es-exam-link-copy>span {font-size:10px;line-height:1.5;}
#es-app[data-suite="true"] .es-sidebar-add {min-height:40px;flex-shrink:0;}
#es-app[data-suite="true"] .es-sidebar-footer {padding:22px 6px 0;line-height:1.6;font-size:10px;}
#es-app[data-suite="true"] .suite-companion-note {border:0;border-top:1px solid var(--es-line);border-radius:0;margin:0 0 20px;padding:16px 0 0;background:transparent;}
#es-app[data-suite="true"] .suite-companion-note summary {display:flex;align-items:center;gap:8px;font-size:12px;font-weight:600;line-height:1.4;list-style:none;color:var(--es-text);}
#es-app[data-suite="true"] .suite-companion-note summary::-webkit-details-marker {display:none;}
#es-app[data-suite="true"] .suite-companion-note summary::after {content:"+";margin-left:auto;color:var(--es-accent);font-size:17px;}
#es-app[data-suite="true"] .suite-companion-note[open] summary::after {content:"−";}
#es-app[data-suite="true"] .suite-companion-note summary small {display:block;color:var(--es-muted);font-weight:400;font-size:11px;}
#es-app[data-suite="true"] .suite-companion-note .es-sidebar-sprout {margin:0;flex:0 0 28px;width:28px;}
#es-app[data-suite="true"] .suite-companion-note img {width:28px;height:36px;object-fit:contain;}
#es-app[data-suite="true"] .suite-companion-note p {padding-top:10px;font-size:11px;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-privacy-label {margin-bottom:5px;}
html #es-app[data-suite="true"] .es-main {
  min-height:0;min-width:0;width:100%;max-width:none;margin:0;padding:28px var(--studio-gutter) 32px;
  overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;scrollbar-gutter:stable;
  scrollbar-width:thin;scrollbar-color:var(--es-line) transparent;scroll-padding:20px;
}
#es-app[data-suite="true"] .es-main :focus-visible {scroll-margin-block:24px;}
#es-app[data-suite="true"][data-page="setup"] .es-main {display:flex;flex-direction:column;overflow:hidden;padding-top:24px;padding-bottom:0;}
#es-app[data-suite="true"] .suite-exam-editor {display:flex;flex-direction:column;flex:1;min-height:0;max-width:1320px;width:100%;margin:0 auto;border-radius:0;background:transparent;}
#es-app[data-suite="true"] .suite-form-heading {display:flex;justify-content:space-between;align-items:flex-start;gap:18px;flex:0 0 auto;padding:0 0 20px;}
#es-app[data-suite="true"] .suite-form-heading .es-label {font-size:10px;letter-spacing:1.4px;line-height:1.5;}
#es-app[data-suite="true"] .suite-form-heading h1 {font:500 clamp(26px,2.6vw,36px)/1.16 var(--world-font,"Segoe UI");letter-spacing:-.6px;margin-top:7px;color:var(--es-text);outline:0;}
#es-app[data-suite="true"] .suite-form-heading p {font-size:12px;line-height:1.65;margin-top:7px;max-width:76ch;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-unsaved-state {font-size:10px;line-height:1.5;border:1px solid var(--es-line);border-radius:999px;padding:5px 9px;white-space:nowrap;margin-top:5px;color:var(--es-muted);background:var(--es-surface);}
#es-app[data-suite="true"] .es-stepper {display:flex;align-items:stretch;gap:4px;border:0;margin:0 0 20px;padding:0;flex:0 0 auto;max-width:640px;width:100%;}
#es-app[data-suite="true"] .es-step {flex:1;display:flex;align-items:center;gap:9px;padding:8px 10px;color:var(--es-muted);border:1px solid transparent;border-radius:10px;min-width:0;font-size:12px;line-height:1.35;min-height:44px;background:transparent;white-space:normal;}
#es-app[data-suite="true"] .es-step:disabled {opacity:1;cursor:default;}
#es-app[data-suite="true"] .es-step b {display:grid;place-items:center;flex:0 0 25px;width:25px;height:25px;border:1px solid var(--es-line);border-radius:8px;background:var(--es-surface);color:var(--es-muted);font:600 12px/1 system-ui;}
#es-app[data-suite="true"] .es-step b svg {height:14px;width:14px;}
#es-app[data-suite="true"] .es-step.active {background:var(--es-soft);border-color:var(--es-line);color:var(--es-accent);}
#es-app[data-suite="true"] .es-step.active b {background:var(--es-accent);color:var(--es-on-accent);border-color:var(--es-accent);}
#es-app[data-suite="true"] .es-step.complete {color:var(--es-accent);}
#es-app[data-suite="true"] .es-step.complete:hover {background:var(--es-surface);border-color:var(--es-line);}
#es-app[data-suite="true"] .suite-setup-scroll {min-height:0;flex:1;overflow-y:auto;overflow-x:hidden;padding:2px 4px 24px;scrollbar-gutter:stable;scroll-padding:24px;scrollbar-width:thin;scrollbar-color:var(--es-line) transparent;overscroll-behavior:contain;}
#es-app[data-suite="true"] .suite-setup-grid {display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:22px;align-items:start;}
#es-app[data-suite="true"] .suite-editor-fields {
  min-width:0;padding:26px;border:1px solid var(--es-line);border-radius:var(--studio-radius);
  background:var(--es-surface);box-shadow:0 12px 28px #0000000a;container-type:inline-size;
}
#es-app[data-suite="true"] .suite-editor-fields>.es-field:last-child {margin-bottom:0;}
#es-app[data-suite="true"] .suite-editor-fields>h2 {font:600 16px/1.45 "Segoe UI",system-ui,sans-serif;letter-spacing:-.15px;}
#es-app[data-suite="true"] .suite-editor-fields>.es-intro {font-size:12px;line-height:1.7;margin:8px 0 20px;max-width:72ch;}
#es-app[data-suite="true"] .es-field {font-size:13px;font-weight:600;line-height:1.45;gap:8px;margin-bottom:24px;min-width:0;}
#es-app[data-suite="true"] .es-field :is(input,textarea,select) {font:400 14px/1.5 "Segoe UI",system-ui,sans-serif;min-width:0;max-width:100%;min-height:44px;border-radius:10px;border:1px solid var(--es-line);padding:11px 12px;background:var(--es-bg);color:var(--es-text);}
#es-app[data-suite="true"] .es-field textarea {height:110px;min-height:100px;resize:vertical;}
#es-app[data-suite="true"] .es-field small {font-size:11px;font-weight:400;line-height:1.65;color:var(--es-muted);margin:0;max-width:76ch;}
#es-app[data-suite="true"] .es-field :is(input,textarea)::placeholder {color:var(--es-muted);opacity:.85;}
#es-app[data-suite="true"] .es-field :is(input,select,textarea):focus {outline:2px solid var(--es-accent);outline-offset:2px;box-shadow:0 0 0 4px color-mix(in srgb,var(--es-accent) 10%,transparent);}
#es-app[data-suite="true"] .es-form-grid {gap:20px;min-width:0;}
#es-app[data-suite="true"] .suite-editor-aside {position:sticky;top:0;min-width:0;}
#es-app[data-suite="true"] .suite-setup-summary {margin:0;padding:0;border:1px solid var(--es-line);border-radius:var(--studio-radius);background:var(--es-surface);box-shadow:0 12px 28px #00000008;overflow:hidden;}
#es-app[data-suite="true"] .suite-setup-summary>summary {display:flex;gap:8px;align-items:center;list-style:none;cursor:pointer;font-size:12px;font-weight:600;padding:15px 18px;line-height:1.5;color:var(--es-text);}
#es-app[data-suite="true"] .suite-setup-summary>summary::-webkit-details-marker {display:none;}
#es-app[data-suite="true"] .suite-setup-summary>summary>svg {width:17px;height:17px;color:var(--es-accent);}
#es-app[data-suite="true"] .suite-setup-summary>summary>span {margin-left:auto;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-setup-summary[open]>summary {border-bottom:1px solid var(--es-line);}
#es-app[data-suite="true"] .suite-summary-scenery {height:108px;background:var(--world-art,none) center 52%/cover,var(--es-soft);border-bottom:1px solid var(--es-line);}
html:not([data-atelier-scenery="true"]) #es-app[data-suite="true"] .suite-summary-scenery {display:none;}
#es-app[data-suite="true"] :is(.suite-summary-content,.suite-practice-summary-content) {padding:20px 18px;}
#es-app[data-suite="true"] :is(.suite-summary-content,.suite-practice-summary-content)>.es-label {font-size:9px;letter-spacing:1.2px;}
#es-app[data-suite="true"] :is(.suite-summary-content,.suite-practice-summary-content)>h2 {font:500 23px/1.25 var(--world-font,"Segoe UI");color:var(--es-text);overflow-wrap:anywhere;margin-top:7px;letter-spacing:-.35px;}
#es-app[data-suite="true"] .suite-summary-facts {padding:0;margin:16px 0 0;}
#es-app[data-suite="true"] .suite-summary-facts>div {padding:12px 0;border-top:1px solid var(--es-line);}
#es-app[data-suite="true"] .suite-summary-facts dt {display:flex;align-items:center;gap:7px;font-size:10px;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-summary-facts dt svg {width:14px;height:14px;}
#es-app[data-suite="true"] .suite-summary-facts dd {margin:5px 0 0;font-size:12px;font-weight:500;line-height:1.5;overflow-wrap:anywhere;}
#es-app[data-suite="true"] .suite-summary-facts small {display:block;font-size:10px;line-height:1.55;font-weight:400;color:var(--es-muted);margin-top:4px;}
#es-app[data-suite="true"] .suite-scope-preview {display:flex;flex-direction:column;gap:8px;border-top:1px solid var(--es-line);padding-top:14px;}
#es-app[data-suite="true"] .suite-scope-preview>span:not(.es-label) {font-size:11px;line-height:1.5;overflow-wrap:anywhere;}
#es-app[data-suite="true"] .suite-scope-preview small {color:var(--es-muted);font-size:10px;}
#es-app[data-suite="true"] .suite-summary-filter {font-size:11px;padding-top:14px;color:var(--es-warning);}
#es-app[data-suite="true"] .suite-summary-note {font-size:10px;line-height:1.65;color:var(--es-muted);padding-top:14px;border-top:1px solid var(--es-line);margin-top:14px;}
#es-app[data-suite="true"] .suite-summary-note svg {width:13px;height:13px;color:var(--es-accent);vertical-align:-2px;margin-right:3px;}
#es-app[data-suite="true"] .es-form-actions {flex-shrink:0;display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;margin:0;padding:16px 0;min-height:72px;background:var(--es-bg);border-top:1px solid var(--es-line);position:relative;z-index:2;}
#es-app[data-suite="true"] .es-form-actions button {min-height:42px;padding:10px 18px;font-size:13px;border-radius:10px;white-space:nowrap;}
#es-app[data-suite="true"] .es-form-actions .es-primary {min-width:125px;}
#es-app[data-suite="true"] .suite-save-hint {font-size:10px;color:var(--es-muted);margin-right:auto;}
#es-app[data-suite="true"] .es-bulk-bar {padding:14px;gap:10px;background:var(--es-bg);border-radius:12px;flex-wrap:wrap;}
#es-app[data-suite="true"] .es-bulk-controls {flex-wrap:wrap;gap:12px;}
#es-app[data-suite="true"] .es-bulk-controls label {display:flex;gap:6px;align-items:center;flex-wrap:wrap;font-size:11px;}
#es-app[data-suite="true"] .es-deck-option {min-width:0;align-items:center;grid-template-columns:20px minmax(0,1fr) 118px 64px;gap:9px;}
#es-app[data-suite="true"] .es-deck-option>label {font-size:12px;overflow-wrap:anywhere;line-height:1.45;}
#es-app[data-suite="true"] .es-deck-option :is(select,input[type="number"]) {font-size:11px;min-height:36px;min-width:0;}
#es-app[data-suite="true"] .es-deck-option input[type="checkbox"] {width:17px;height:17px;}
#es-app[data-suite="true"] .es-deck-picker-head {font-size:10px;grid-template-columns:minmax(0,1fr) 118px 64px;gap:9px;}
#es-app[data-suite="true"] #es-deck-options {max-height:none;overflow:visible;}
#es-app[data-suite="true"] .es-choice-grid {gap:10px;}
#es-app[data-suite="true"] .es-choice {min-width:0;padding:15px 12px;}
#es-app[data-suite="true"] .es-choice strong {font-size:12px;line-height:1.5;}
#es-app[data-suite="true"] .es-choice span {font-size:11px;line-height:1.55;}
#es-app[data-suite="true"] .es-weekdays {display:flex;flex-wrap:wrap;gap:7px;}
#es-app[data-suite="true"] .es-weekday {min-width:36px;min-height:38px;padding:8px;font-size:12px;}
/* Practice keeps every original option and previews a read-only configuration. */
#es-app[data-suite="true"] .suite-practice-heading {max-width:1060px;margin-bottom:24px;}
#es-app[data-suite="true"] .suite-practice-heading>h1 {font-family:var(--world-font,"Segoe UI");font-size:clamp(26px,2.7vw,36px);font-weight:500;line-height:1.2;}
#es-app[data-suite="true"] .suite-practice-heading>.es-intro {font-size:12px;line-height:1.65;max-width:90ch;margin:12px 0;}
#es-app[data-suite="true"] .suite-schedule-safe {display:inline-flex;align-items:center;gap:7px;color:var(--es-accent);border:1px solid var(--es-line);border-radius:8px;background:var(--es-soft);font-size:11px;padding:8px 10px;}
#es-app[data-suite="true"] .suite-schedule-safe svg {width:15px;height:15px;}
#es-app[data-suite="true"] .suite-practice-grid {display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:22px;align-items:start;max-width:1320px;margin:auto;}
html #es-app[data-suite="true"] .es-practice-card {padding:26px;border-radius:var(--studio-radius);min-width:0;max-width:100%;}
#es-app[data-suite="true"] .suite-practice-aside {position:sticky;top:0;min-width:0;}
#es-app[data-suite="true"] .suite-session-size {display:flex;align-items:baseline;gap:10px;margin-top:20px;color:var(--es-accent);}
#es-app[data-suite="true"] .suite-session-size strong {font-size:40px;font-weight:500;line-height:1;letter-spacing:-1px;}
#es-app[data-suite="true"] .suite-session-size span {font-size:10px;color:var(--es-muted);}
#es-app[data-suite="true"] .suite-session-tags {display:flex;gap:6px;flex-wrap:wrap;}
#es-app[data-suite="true"] .suite-session-tags span {font-size:10px;padding:5px 7px;background:var(--es-soft);border-radius:5px;color:var(--es-accent);}
#es-app[data-suite="true"] .suite-summary-footnote {font-size:10px;line-height:1.7;color:var(--es-muted);margin-top:12px;}
#es-app[data-suite="true"] .es-mode-switch {gap:10px;margin-bottom:26px;}
#es-app[data-suite="true"] .es-mode-switch>button {padding:16px;font-size:13px;}
#es-app[data-suite="true"] .es-mode-switch>button>span {font-size:11px;line-height:1.6;}
#es-app[data-suite="true"] .es-session-presets {gap:6px;margin-bottom:24px;}
#es-app[data-suite="true"] .es-session-presets button {min-height:34px;}
#es-app[data-suite="true"] .es-modal {max-height:calc(100dvh - 36px);max-width:calc(100vw - 28px);overflow-y:auto;overscroll-behavior:contain;}
#es-app[data-suite="true"] .es-toast {bottom:16px;max-width:min(600px,calc(100vw - 32px));font-size:13px;line-height:1.55;z-index:30;}
#es-app[data-suite="true"] button:hover {transform:none;}
@container(max-width:540px) {
  #es-app[data-suite="true"] .suite-editor-fields .es-form-grid {grid-template-columns:1fr;gap:0;}
  #es-app[data-suite="true"] .es-deck-option {grid-template-columns:20px minmax(0,1fr) 64px;}
  #es-app[data-suite="true"] .es-deck-option>label {grid-column:2/-1;}
  #es-app[data-suite="true"] .es-deck-option>select {grid-column:2;}
  #es-app[data-suite="true"] .es-deck-option>input[type="number"] {grid-column:3;}
  #es-app[data-suite="true"] .es-deck-picker-head {display:none;}
  #es-app[data-suite="true"] .es-choice-grid {grid-template-columns:1fr;}
}
@media(max-width:1179px) {
  #es-app[data-suite="true"] .suite-setup-grid,#es-app[data-suite="true"] .suite-practice-grid {grid-template-columns:minmax(0,1fr);}
  #es-app[data-suite="true"] .suite-editor-aside,#es-app[data-suite="true"] .suite-practice-aside {position:static;grid-row:1;}
  #es-app[data-suite="true"] .suite-summary-scenery {height:80px;}
  #es-app[data-suite="true"] .suite-setup-summary[open] :is(.suite-summary-content,.suite-practice-summary-content) {padding:18px;}
  #es-app[data-suite="true"] .suite-save-hint {display:none;}
}
@media(max-width:920px) {
  html #es-app[data-suite="true"] .es-app-header {grid-template-columns:minmax(0,1fr) auto;grid-template-areas:"brand world" "tools tools" "nav nav";gap:8px 12px!important;padding:10px 18px 0!important;}
  #es-app[data-suite="true"] .suite-tool-links {width:100%;display:flex;gap:8px;}
  #es-app[data-suite="true"] .suite-tool-links button {flex:1;min-height:36px;}
  #es-app[data-suite="true"] .suite-brand-copy {gap:8px;}
  #es-app[data-suite="true"] .es-header-note {font-size:11px;}
  #es-app[data-suite="true"] .es-layout {grid-template-columns:176px minmax(0,1fr);}
  html #es-app[data-suite="true"] .es-main {padding:22px 18px;}
  #es-app[data-suite="true"][data-page="setup"] .es-main {padding-bottom:0;}
  #es-app[data-suite="true"] .suite-editor-fields {padding:20px;}
  #es-app[data-suite="true"] .suite-unsaved-state {display:none;}
}
@media(max-width:700px) {
  #es-app[data-suite="true"] .es-layout {grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr);}
  #es-app[data-suite="true"] .suite-exams-toggle {display:flex;align-items:center;gap:8px;border:0;border-radius:0;border-bottom:1px solid var(--es-line);min-height:38px;padding:8px 18px;font-size:12px;background:var(--es-surface);}
  #es-app[data-suite="true"] .suite-exams-toggle svg {width:16px;height:16px;color:var(--es-accent);}
  #es-app[data-suite="true"] .suite-exams-toggle>b {margin-left:auto;color:var(--es-muted);}
  html #es-app[data-suite="true"] .es-sidebar {display:none;}
  html #es-app[data-suite="true"][data-rail-open="true"] .es-sidebar {display:flex;position:absolute;top:38px;left:0;right:0;max-height:min(55%,300px);padding:18px;z-index:12;background:var(--es-surface);box-shadow:0 20px 40px #0004;border:0;border-bottom:1px solid var(--es-line);}
  #es-app[data-suite="true"] .es-exam-list {flex-direction:column;overflow:visible;}
  #es-app[data-suite="true"] .es-exam-link {width:100%;min-width:0;}
  #es-app[data-suite="true"] .es-sidebar-footer {display:none;}
  #es-app[data-suite="true"] .es-sidebar-add {width:100%;}
  #es-app[data-suite="true"] .suite-form-heading {padding-bottom:12px;gap:8px;}
  #es-app[data-suite="true"] .suite-form-heading h1 {font-size:27px;}
  #es-app[data-suite="true"] .suite-form-heading p {font-size:11px;margin-top:5px;}
  #es-app[data-suite="true"] .es-stepper {margin-bottom:12px;gap:3px;}
  #es-app[data-suite="true"] .es-step {font-size:11px;padding:6px 7px;min-height:40px;gap:6px;}
  #es-app[data-suite="true"] .es-step b {width:21px;height:23px;flex-basis:21px;font-size:10px;border-radius:6px;}
  #es-app[data-suite="true"] .suite-setup-scroll {padding-left:2px;padding-right:2px;scrollbar-gutter:auto;}
  #es-app[data-suite="true"] .suite-setup-grid {gap:12px;}
  #es-app[data-suite="true"] .suite-editor-fields {padding:18px;}
  #es-app[data-suite="true"] .es-form-actions {padding:12px 0;min-height:66px;gap:6px;}
  #es-app[data-suite="true"] .es-form-actions button {padding:10px 12px;font-size:12px;min-height:40px;}
  #es-app[data-suite="true"] .es-form-actions .es-primary {min-width:104px;}
  #es-app[data-suite="true"] .es-form-actions .es-flex {gap:6px;}
  #es-app[data-suite="true"] .es-form-grid {grid-template-columns:1fr;gap:0;}
}
@media(max-width:460px) {
  html #es-app[data-suite="true"] .es-app-header {padding:8px 12px 0!important;gap:6px 8px!important;}
  #es-app[data-suite="true"] .es-brand-mark {width:25px;flex-basis:25px;height:30px;}
  #es-app[data-suite="true"] .es-brand-mark img {width:25px;height:30px;}
  #es-app[data-suite="true"] .suite-brand-copy {flex-direction:column;gap:0;align-items:flex-start;}
  #es-app[data-suite="true"] .suite-brand-copy>strong {font-size:20px;}
  #es-app[data-suite="true"] .es-header-note {font-size:9px!important;}
  #es-app[data-suite="true"] .suite-world-switch {font-size:10px;gap:5px;}
  #es-app[data-suite="true"] .suite-world-switch select {width:112px;max-width:112px;min-height:36px;font-size:12px;padding:6px 8px;}
  #es-app[data-suite="true"] .suite-tool-links {gap:5px;}
  #es-app[data-suite="true"] .suite-tool-links button {padding:7px 6px;font-size:12px;gap:6px;min-height:36px;}
  #es-app[data-suite="true"] .suite-tool-links svg {height:14px;width:14px;}
  #es-app[data-suite="true"] .es-top-nav {gap:2px;padding:4px 0;}
  #es-app[data-suite="true"] .es-top-nav button {flex:1;font-size:11px;padding:8px 5px;min-height:36px;gap:4px;}
  #es-app[data-suite="true"] .es-top-nav button svg {display:none;}
  html #es-app[data-suite="true"] .es-main {padding:16px 12px;}
  #es-app[data-suite="true"][data-page="setup"] .es-main {padding-bottom:0;}
  #es-app[data-suite="true"] .suite-form-heading p {display:none;}
  #es-app[data-suite="true"] .es-field :is(input,select,textarea) {font-size:13px;}
  #es-app[data-suite="true"] .es-step {font-size:10px;padding:5px;gap:5px;}
  #es-app[data-suite="true"] .es-step b {width:19px;flex-basis:19px;}
  html #es-app[data-suite="true"] .es-practice-card {padding:18px;}
  #es-app[data-suite="true"] .es-mode-switch>button {padding:13px;}
}
@media(max-height:480px) {
  html.es-host:has(#es-app[data-suite="true"]),html.es-host:has(#es-app[data-suite="true"]) body {overflow-y:auto;}
  #es-app[data-suite="true"] {min-height:480px;}
}
@media(prefers-reduced-motion:no-preference) {
  html[data-atelier-world-motion="true"] #es-app[data-suite="true"] :is(button,input,textarea,select) {transition:background-color .14s ease,border-color .14s ease,box-shadow .14s ease;}
}
@media(prefers-reduced-motion:reduce) {
  #es-app[data-suite="true"] *,#es-app[data-suite="true"] *::before,#es-app[data-suite="true"] *::after {animation:none!important;transition:none!important;scroll-behavior:auto!important;}
}
@media(forced-colors:active) {
  #es-app[data-suite="true"] :is(.suite-editor-fields,.suite-setup-summary,.suite-unsaved-state) {border:1px solid CanvasText;}
  #es-app[data-suite="true"] .suite-summary-scenery {display:none;}
  #es-app[data-suite="true"] .es-step.active {border:2px solid Highlight;}
}

/* Native form affordances must follow the selected world, not an old dark preset. */
html[data-atelier-world-enabled="true"] #es-app[data-suite="true"] {color-scheme:var(--ats-scheme);}
#es-app[data-suite="true"] :is(input,select,textarea) {color-scheme:inherit;}
#es-app[data-suite="true"] input[type="checkbox"] {accent-color:var(--es-accent);}
html #es-app[data-suite="true"] .suite-practice-grid>.es-practice-card {margin:0;}

web/world-finishes.css:
/* Final world finishes. Presentation only; no card geometry or external assets. */
:host([data-owner="atelier"][data-theme="obsidian"]),.mini-screen[data-theme="obsidian"],html[data-atelier-world-enabled="true"][data-atelier-world="obsidian"]{
 --finish-aperture:18px 5px 18px 5px;--finish-angle:120deg;--finish-alpha:0.035;--finish-pattern:linear-gradient(123deg,transparent 30%,var(--finish-line) 30.1%,transparent 30.4%,transparent 77%,var(--finish-line) 77.1%,transparent 77.4%);
}
:host([data-owner="atelier"][data-theme="glacier"]),.mini-screen[data-theme="glacier"],html[data-atelier-world-enabled="true"][data-atelier-world="glacier"]{
 --finish-aperture:6px 22px 6px 22px;--finish-angle:145deg;--finish-alpha:0.04;--finish-pattern:linear-gradient(155deg,transparent 55%,var(--finish-line) 55.1%,transparent 55.4%),linear-gradient(25deg,transparent 75%,var(--finish-line) 75.1%,transparent 75.4%);
}
:host([data-owner="atelier"][data-theme="rose"]),.mini-screen[data-theme="rose"],html[data-atelier-world-enabled="true"][data-atelier-world="rose"]{
 --finish-aperture:70px 70px 14px 14px;--finish-angle:110deg;--finish-alpha:0.025;--finish-pattern:radial-gradient(ellipse at 90% 130%,transparent 52%,var(--finish-line) 52.2%,transparent 52.5%,transparent 64%,var(--finish-line) 64.2%,transparent 64.5%);
}
:host([data-owner="atelier"][data-theme="bloom"]),.mini-screen[data-theme="bloom"],html[data-atelier-world-enabled="true"][data-atelier-world="bloom"]{
 --finish-aperture:32px 10px 32px 10px;--finish-angle:135deg;--finish-alpha:0.025;--finish-pattern:linear-gradient(90deg,transparent 49.8%,var(--finish-line) 50%,transparent 50.2%),linear-gradient(0deg,transparent 49.8%,var(--finish-line) 50%,transparent 50.2%);
}
:host([data-owner="atelier"][data-theme="linen"]),.mini-screen[data-theme="linen"],html[data-atelier-world-enabled="true"][data-atelier-world="linen"]{
 --finish-aperture:5px;--finish-angle:90deg;--finish-alpha:0.023;--finish-pattern:repeating-linear-gradient(90deg,transparent 0 3px,var(--finish-line) 3px 4px),repeating-linear-gradient(0deg,transparent 0 3px,var(--finish-line) 3px 4px);
}
:host([data-owner="atelier"][data-theme="matcha"]),.mini-screen[data-theme="matcha"],html[data-atelier-world-enabled="true"][data-atelier-world="matcha"]{
 --finish-aperture:8px 24px 8px 24px;--finish-angle:160deg;--finish-alpha:0.025;--finish-pattern:repeating-linear-gradient(90deg,transparent 0 79px,var(--finish-line) 79px 80px),repeating-linear-gradient(0deg,transparent 0 79px,var(--finish-line) 79px 80px);
}
:host([data-owner="atelier"][data-theme="midnight"]),.mini-screen[data-theme="midnight"],html[data-atelier-world-enabled="true"][data-atelier-world="midnight"]{
 --finish-aperture:7px;--finish-angle:100deg;--finish-alpha:0.04;--finish-pattern:linear-gradient(90deg,var(--finish-line) 1px,transparent 1px),linear-gradient(0deg,var(--finish-line) 1px,transparent 1px);
}
:host([data-owner="atelier"][data-theme="peach"]),.mini-screen[data-theme="peach"],html[data-atelier-world-enabled="true"][data-atelier-world="peach"]{
 --finish-aperture:36px 9px 36px 9px;--finish-angle:140deg;--finish-alpha:0.025;--finish-pattern:radial-gradient(ellipse at 85% 110%,transparent 55%,var(--finish-line) 55.2%,transparent 55.5%,transparent 71%,var(--finish-line) 71.2%,transparent 71.5%);
}
:host([data-owner="atelier"][data-theme="forest"]),.mini-screen[data-theme="forest"],html[data-atelier-world-enabled="true"][data-atelier-world="forest"]{
 --finish-aperture:46px 46px 12px 12px;--finish-angle:125deg;--finish-alpha:0.04;--finish-pattern:linear-gradient(118deg,transparent 42%,var(--finish-line) 42.2%,transparent 43.5%,transparent 70%,var(--finish-line) 70.2%,transparent 71.5%);
}
:host([data-owner="atelier"][data-theme="tidal"]),.mini-screen[data-theme="tidal"],html[data-atelier-world-enabled="true"][data-atelier-world="tidal"]{
 --finish-aperture:32px 12px 44px 12px;--finish-angle:150deg;--finish-alpha:0.023;--finish-pattern:repeating-radial-gradient(ellipse at 100% 130%,transparent 0 45px,var(--finish-line) 46px 47px,transparent 48px 83px);
}
:host([data-owner="atelier"][data-theme="ember"]),.mini-screen[data-theme="ember"],html[data-atelier-world-enabled="true"][data-atelier-world="ember"]{
 --finish-aperture:8px 28px 8px 28px;--finish-angle:115deg;--finish-alpha:0.04;--finish-pattern:repeating-linear-gradient(168deg,transparent 0 46px,var(--finish-line) 47px 48px,transparent 49px 108px);
}
:host([data-owner="atelier"][data-theme="celestial"]),.mini-screen[data-theme="celestial"],html[data-atelier-world-enabled="true"][data-atelier-world="celestial"]{
 --finish-aperture:54px 54px 12px 12px;--finish-angle:130deg;--finish-alpha:0.035;--finish-pattern:radial-gradient(ellipse at 110% -10%,transparent 52%,var(--finish-line) 52.2%,transparent 52.5%,transparent 67%,var(--finish-line) 67.2%,transparent 67.5%);
}

:host([data-owner="atelier"]){--finish-line:color-mix(in srgb,var(--accent) 10%,transparent);--finish-sheen:linear-gradient(var(--finish-angle,120deg),rgba(255,255,255,var(--finish-alpha,.03)),transparent 60%);}
html[data-atelier-world-enabled="true"]{--finish-line:color-mix(in srgb,var(--ats-accent) 10%,transparent);--finish-sheen:linear-gradient(var(--finish-angle,120deg),rgba(255,255,255,var(--finish-alpha,.03)),transparent 60%);}
/* Materials occupy chapter panels, not the interactive fields or reading surface. */
:host([data-owner="atelier"][data-ambience="true"]) .task-focus.quiet-focus {background-image:var(--finish-pattern),linear-gradient(var(--finish-angle),var(--hero),var(--hero-end));}
:host([data-owner="atelier"]) .world-window {border-radius:var(--finish-aperture);box-shadow:inset 0 0 0 1px rgba(255,255,255,.06);}
:host([data-owner="atelier"]) :is(.revisit-column,.suite-plan,.deck-detail,.tools-spotlight){background-image:var(--finish-sheen);}
:host([data-owner="atelier"]) .lecture-row:hover {background-color:var(--raised);}
:host([data-owner="atelier"]) .tool-symbol {border-radius:calc(var(--world-radius) * .5);background:var(--accent-soft);color:var(--accent-strong);border:1px solid var(--line-soft);}
:host([data-owner="atelier"]) :is(.tool-tile,.library-row,.revisit-row){transform:none!important;}
:host([data-owner="atelier"]) .tool-tile:hover {border-color:var(--accent);background-color:var(--raised);}
html[data-atelier-world-enabled="true"][data-atelier-scenery="true"] #es-app :is(.es-hero,.suite-result-hero){background-image:var(--finish-pattern),linear-gradient(var(--finish-angle),var(--es-soft),var(--es-surface));}
html[data-atelier-world-enabled="true"] #es-app :is(.suite-setup-summary,.es-practice-card,.suite-session-safety){background-image:var(--finish-sheen);}
html[data-atelier-world-enabled="true"] #es-app .suite-summary-scenery {border-radius:var(--finish-aperture);}
/* Typography has character in headings, consistency in labels and editable text. */
:host([data-owner="atelier"]) :is(.revisit-column h2,.tools-group-heading h2){font-family:var(--world-font);font-size:19px;font-weight:500;line-height:1.35;}
:host([data-owner="atelier"]) :is(.card-title,.library-row strong,.lecture-name strong){font-family:"Segoe UI",system-ui,sans-serif;font-weight:600;letter-spacing:0;}
:host([data-owner="atelier"]) :is(.focus-metric span,.deck-card .countline,.library-foot,.scope-note,.study-block-subtitle){font-size:11px;line-height:1.6;}
html[data-atelier-world-enabled="true"] #es-app :is(.suite-session-kicker,.suite-form-kicker){letter-spacing:1.1px;}
/* Illustrated, labelled world chooser. No screenshots masquerade as live controls. */
.world-browser-head{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap;margin:18px 0 14px;}
.world-browser-head p{font:12px/1.6 system-ui;color:var(--muted);}
.world-lighting{display:flex;gap:3px;border:1px solid var(--line);background:var(--side);border-radius:10px;padding:3px;}
.world-lighting button{font:12px/1.4 system-ui;padding:7px 12px;border-radius:7px;min-height:32px;color:var(--muted);}
.world-lighting button[aria-pressed="true"]{background:var(--raised);color:var(--text);box-shadow:inset 0 0 0 1px var(--line);}
.world-count{font:12px/1.5 system-ui;color:var(--muted);margin:0 0 12px;}
.themes{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;}
.theme-tile{padding:7px 7px 12px;border-radius:14px;display:flex;flex-direction:column;align-items:stretch;background:var(--panel);min-width:0;transform:none!important;box-shadow:none!important;}
.theme-tile[hidden]{display:none!important;}
.theme-tile.selected{outline:2px solid var(--accent-strong);outline-offset:2px;}
.theme-tile .mini-screen{display:block;position:relative;isolation:isolate;height:118px;border-radius:var(--finish-aperture);background:var(--world-art) center/cover,var(--hero);padding:0;}
.theme-tile .mini-screen::after{content:none!important;}
.theme-material-sample{display:flex;gap:4px;position:absolute;left:10px;bottom:9px;right:10px;border-radius:7px;padding:6px;background:var(--panel);border:1px solid var(--line);}
.theme-material-sample i{height:6px;display:block;border:0;border-radius:2px;width:20%;background:var(--accent);}
.theme-material-sample i:nth-child(2){background:var(--text);width:35%;opacity:.55;}
.theme-material-sample i:nth-child(3){background:var(--muted);width:18%;margin-left:auto;}
.theme-light{font:10px/1.4 system-ui;color:var(--text);background:var(--panel);padding:3px 7px;border-radius:5px;border:1px solid var(--line);position:absolute;right:10px;top:auto;bottom:36px;}
.theme-tile .tile-label{padding:11px 5px 0;align-items:center;min-height:29px;}
.theme-tile .tile-label strong{font-size:13px;line-height:1.35;color:var(--text);}
.theme-tile>small{font:11px/1.6 system-ui;padding:5px 5px 0;color:var(--muted);}
.theme-title{font:13px/1.5 var(--world-font,system-ui);color:var(--text);padding:5px 5px 0;}
.theme-tile .theme-check{width:20px;height:20px;color:var(--accent-strong);}
.theme-filter-empty{padding:18px;font:13px/1.6 system-ui;color:var(--muted);}
:host([data-ambience="false"]) .mini-screen {background-image:none!important;}
:host([data-ambience="false"]) .mini-screen .theme-material-sample {bottom:18px;}
@media(max-width:600px){.themes{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;}.theme-tile .mini-screen{height:100px;}.theme-tile .tile-label strong{font-size:12px;}.theme-title{font-size:12px;}}
@media(max-width:350px){.themes{gap:9px;}.theme-tile{padding:5px 5px 9px;}.theme-tile .mini-screen{height:86px;}.theme-light{font-size:9px;right:8px;bottom:34px;}.world-lighting button{padding-inline:9px;}}

/* A candidate world demonstrates its own heading family without loading fonts. */
.theme-tile[data-theme-choice="obsidian"] .theme-title{font-family:"Segoe UI", system-ui, sans-serif;}
.theme-tile[data-theme-choice="glacier"] .theme-title{font-family:"Segoe UI", system-ui, sans-serif;}
.theme-tile[data-theme-choice="rose"] .theme-title{font-family:Georgia, "Times New Roman", serif;}
.theme-tile[data-theme-choice="bloom"] .theme-title{font-family:Georgia, "Times New Roman", serif;}
.theme-tile[data-theme-choice="linen"] .theme-title{font-family:Georgia, "Times New Roman", serif;}
.theme-tile[data-theme-choice="matcha"] .theme-title{font-family:Georgia, "Times New Roman", serif;}
.theme-tile[data-theme-choice="midnight"] .theme-title{font-family:ui-monospace, Consolas, monospace;}
.theme-tile[data-theme-choice="peach"] .theme-title{font-family:Georgia, "Times New Roman", serif;}
.theme-tile[data-theme-choice="forest"] .theme-title{font-family:Georgia, "Times New Roman", serif;}
.theme-tile[data-theme-choice="tidal"] .theme-title{font-family:"Segoe UI", system-ui, sans-serif;}
.theme-tile[data-theme-choice="ember"] .theme-title{font-family:"Segoe UI", system-ui, sans-serif;}
.theme-tile[data-theme-choice="celestial"] .theme-title{font-family:Georgia, "Times New Roman", serif;}

web/worlds-home.css:
/* Study Worlds · composition, materials and scenery. No fixed overlay on controls. */
:host{--world-font:"Segoe UI",system-ui,sans-serif;--world-radius:20px;--world-art:none}
:host([data-owner="atelier"]) .main{background:radial-gradient(ellipse at 92% 0%,var(--hero-end),transparent 65%),var(--bg);}
:host([data-owner="atelier"]) .sidebar{background:linear-gradient(170deg,var(--side),var(--bg));border-right:1px solid var(--line-soft);}
:host([data-owner="atelier"]) .topbar{background:var(--bg);border-bottom:1px solid var(--line-soft);box-shadow:none;}
:host([data-owner="atelier"]) .quiet-focus{grid-template-columns:minmax(0,1fr) minmax(240px,32%);border-radius:var(--world-radius);background:linear-gradient(125deg,var(--hero),var(--hero-end));border:1px solid var(--line);box-shadow:0 18px 55px var(--shadow);overflow:hidden;}
:host([data-owner="atelier"]) .quiet-focus .focus-intro{padding:36px 32px;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;}
:host([data-owner="atelier"]) .quiet-focus h1{font-family:var(--world-font);font-size:clamp(30px,3.1vw,49px);font-weight:500;line-height:1.1;letter-spacing:-1.1px;max-width:20ch;}
:host([data-owner="atelier"]) .quiet-focus p{font-size:13px;line-height:1.75;max-width:54ch;color:var(--muted);margin-top:16px;}
:host([data-owner="atelier"]) .focus-actions{gap:9px;margin-top:26px;}
:host([data-owner="atelier"]) .focus-actions .secondary{background:transparent;border-color:var(--line);}
:host([data-owner="atelier"]) .focus-agenda{padding:16px 16px 18px 0;background:transparent;border:0;display:flex;flex-direction:column;gap:9px;min-width:0;}
.world-window{display:block;position:relative;width:100%;min-height:155px;aspect-ratio:2.25;background:var(--world-art) center 48%/cover no-repeat,var(--hero);border:1px solid var(--line);border-radius:calc(var(--world-radius) * .65);overflow:hidden;margin:0 0 2px;color:#fff7e5;}
.world-window::after{content:"";position:absolute;inset:45% 0 0;background:linear-gradient(transparent,rgba(5,13,17,.86));pointer-events:none;}
.world-window .world-window-label{position:absolute;inset:auto 16px 13px;z-index:1;display:flex;flex-direction:column;gap:4px;text-shadow:0 1px 8px #000;}
.world-window .world-window-label small{font:9px/1.2 "Segoe UI",sans-serif;letter-spacing:1.7px;text-transform:uppercase;color:#eee8d7;}
.world-window .world-window-label strong{font:22px/1.1 var(--world-font);letter-spacing:-.3px;color:#fff7e5;}
.world-window .world-window-label strong::after{content:" ↗";font:13px system-ui;color:#e4d9c8;}
.world-window:hover{border-color:var(--accent);filter:none;}
:host([data-companion="true"]) .world-window{display:none}
:host([data-ambience="false"]) .world-window{min-height:82px;aspect-ratio:auto;background:var(--panel);color:var(--text);}
:host([data-ambience="false"]) .world-window::after{content:none}
:host([data-ambience="false"]) .world-window-label *{color:var(--text)!important;text-shadow:none}
:host([data-owner="atelier"]) .agenda-label{margin:4px 1px 0;font-size:9px;letter-spacing:1.1px}
:host([data-owner="atelier"]) .agenda-item{margin:0;min-height:63px;padding:10px;border-radius:10px;background:var(--panel);box-shadow:none;}
:host([data-owner="atelier"]) .agenda-copy strong{font-weight:600;font-size:12px}
:host([data-owner="atelier"]) .focus-footer{padding:17px 30px;border-top:1px solid var(--line);background:var(--panel);box-shadow:none;}
:host([data-owner="atelier"]) .focus-metric strong{font-size:25px;font-weight:500;letter-spacing:-.8px}
:host([data-owner="atelier"]) .focus-metric span{font-size:10px}
:host([data-owner="atelier"]) :is(.deck-card,.study-board,.study-section,.study-panel,.lecture-group){border-radius:var(--world-radius);background:var(--panel);box-shadow:0 8px 22px var(--shadow);}
:host([data-owner="atelier"]) :is(.section-heading h2,.suite-section-title){font:500 23px/1.25 var(--world-font);letter-spacing:-.5px}
:host([data-owner="atelier"]) .card-title{font-family:var(--world-font);font-size:19px;line-height:1.25;}
:host([data-owner="atelier"]) .nav-row.active{border-radius:calc(var(--world-radius)*.5);background:var(--accent-soft);box-shadow:inset 2px 0 var(--accent);}
.suite-sidebar-separator{border-top:1px solid var(--line-soft);margin:8px 12px 6px}
.suite-caption{font:9px/1.6 "Segoe UI",sans-serif;letter-spacing:1.6px;color:var(--quiet);padding:4px 13px;text-transform:uppercase}
.suite-exams{margin:24px 0 0;}
.suite-exams-head{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:12px;}
.suite-exams-head p{font-size:11px;color:var(--muted);margin-top:4px}
.suite-plan-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,290px),1fr));gap:12px;}
.suite-plan{border:1px solid var(--line-soft);background:var(--panel);border-radius:calc(var(--world-radius)*.7);padding:18px;min-width:0;position:relative;}
.suite-plan-top{display:flex;gap:12px;align-items:flex-start;}
.suite-plan-index{font:24px/1 var(--world-font);color:var(--accent);opacity:.85;min-width:25px;}
.suite-plan h3{font-size:14px;line-height:1.45;font-weight:600;overflow-wrap:anywhere}
.suite-plan small{font-size:10px;line-height:1.6;color:var(--muted);display:block;margin-top:4px}
.suite-plan-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:15px}
.suite-plan-actions button{padding:8px 9px;min-height:31px;font-size:11px;border:1px solid var(--line);border-radius:8px;color:var(--text);background:var(--raised);}
.suite-plan-actions button:first-child{border-color:var(--accent);background:var(--accent-soft);color:var(--accent-strong);}
.suite-plan-actions button:hover{background:var(--hover);}
.suite-hub-empty{display:flex;gap:20px;align-items:center;justify-content:space-between;border:1px solid var(--line);background:var(--panel);border-radius:var(--world-radius);padding:20px;}
.suite-hub-empty strong{font:24px/1.2 var(--world-font)}.suite-hub-empty p{margin-top:7px;font-size:12px;color:var(--muted);line-height:1.6;max-width:600px;}
.suite-draft{margin-bottom:12px;padding:12px 16px;border:1px solid var(--accent);border-radius:10px;font-size:12px;background:var(--accent-soft);display:flex;justify-content:space-between;align-items:center;gap:10px;}
.suite-draft button{font-weight:600;text-decoration:underline;}
.themes{grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;}
.theme-tile{padding:0 0 12px;border-radius:14px;overflow:hidden;background:var(--panel);border:1px solid var(--line);box-shadow:none;}
.theme-tile .mini-screen{background:var(--world-art) center/cover, var(--bg);height:100px;display:block;border:0;border-radius:0;position:relative;}
.theme-tile .mini-side,.theme-tile .mini-content{display:none;}
.theme-tile .mini-screen::after{content:var(--world-title);position:absolute;left:11px;bottom:10px;font:15px/1.1 var(--world-font);color:#fff;max-width:90%;text-shadow:0 1px 7px #000;}
.theme-tile .tile-label{padding:0 12px;margin-top:11px;}.theme-tile>small{padding:0 12px;font-size:10px;line-height:1.6;display:block;color:var(--muted)}
.theme-tile.selected{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent);}
/* Material-specific treatments, not just palette swaps. */
:host([data-theme="linen"][data-owner="atelier"]) .main{background:repeating-linear-gradient(0deg,transparent 0 31px,#927d5910 32px),var(--bg);}
:host([data-theme="linen"]) .quiet-focus{border:1px solid var(--line);outline:1px solid var(--line);outline-offset:5px;box-shadow:0 8px 20px var(--shadow);margin:5px;}
:host([data-theme="linen"]) .focus-actions .primary{border-radius:4px;box-shadow:none}
:host([data-theme="midnight"]) .main{background:linear-gradient(90deg,#78c9b509 1px,transparent 1px),linear-gradient(#78c9b509 1px,transparent 1px),var(--bg);background-size:32px 32px;}
:host([data-theme="midnight"]) .focus-panel{border-left:3px solid var(--accent);box-shadow:none;}
:host([data-theme="midnight"]) .eyebrow{font-family:ui-monospace,monospace;letter-spacing:2px}
:host([data-theme="glacier"]) .quiet-focus{border-top:2px solid var(--accent);box-shadow:0 14px 38px #02121940;}
:host([data-theme="glacier"]) .world-window{border-radius:3px 24px 3px 3px}
:host([data-theme="forest"]) .sidebar{background:radial-gradient(ellipse at 0% 0%,#68815524,transparent 45%),var(--side);}
:host([data-theme="forest"]) .quiet-focus{border:1px solid #68875b80;box-shadow:0 18px 55px #02140d50;}
:host([data-theme="forest"]) .world-window{border-radius:70px 70px 10px 10px;}
:host([data-theme="rose"]) .world-window{border-radius:80px 80px 12px 12px;}
:host([data-theme="rose"]) .quiet-focus{background:linear-gradient(115deg,#ead3db,#f1e3d5);}
:host([data-theme="bloom"]) .quiet-focus{background:linear-gradient(135deg,var(--hero),var(--panel));border-radius:28px 28px 9px 9px;}
:host([data-theme="matcha"]) .sidebar{background:repeating-linear-gradient(90deg,transparent 0 35px,#7f936212 36px),var(--side);}
:host([data-theme="matcha"]) .quiet-focus{border-top:4px solid var(--line);box-shadow:0 9px 25px var(--shadow);}
:host([data-theme="peach"]) .world-window{border-radius:55px 12px 55px 12px;}
:host([data-theme="tidal"]) .quiet-focus{border-bottom:3px solid var(--line);border-radius:28px 28px 40px 12px;}
:host([data-theme="ember"]) .quiet-focus{border:1px solid var(--line);border-left:4px solid var(--accent);}
:host([data-theme="celestial"]) .world-window{border-radius:90px 90px 10px 10px;}
:host([data-theme="celestial"]) .focus-intro .eyebrow{letter-spacing:2.5px;}
/* Passive owner is always a genuine boundary. */
:host([data-companion="true"]) :is(.quiet-focus,.sidebar,.main){background-image:none!important;outline:none;border-radius:18px;}
:host([data-companion="true"]) :is(.quiet-focus h1,.card-title,.section-heading h2){font-family:"Segoe UI",sans-serif!important;}
:host([data-ambience="false"]) :is(.main,.sidebar){background-image:none!important;}
@media(max-width:1100px){:host([data-owner="atelier"]) .quiet-focus{grid-template-columns:minmax(0,1fr) 260px;} .world-window{min-height:133px}.focus-intro{padding:26px!important}.quiet-focus h1{font-size:34px!important}}
@media(max-width:880px){:host([data-owner="atelier"]) .quiet-focus{grid-template-columns:1fr;} :host([data-owner="atelier"]) .focus-agenda{padding:0 22px 20px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.world-window{grid-column:1/-1;min-height:150px;aspect-ratio:4.2}.agenda-label{grid-column:1/-1}.themes{grid-template-columns:repeat(2,minmax(0,1fr));}}
@media(max-width:520px){.suite-exams-head,.suite-hub-empty{align-items:flex-start;flex-direction:column}.focus-agenda{display:flex!important}.world-window{min-height:125px}.theme-tile .mini-screen{height:82px}.suite-plan-actions{gap:7px}}
/* Navigation is a first-class part of the home, not hidden in the footer. */
.unified-topbar{position:sticky;top:0;z-index:12;height:auto;min-height:76px;gap:18px;padding:16px 30px;flex-wrap:wrap;}
.unified-topbar .topbar-left{flex:0 1 auto;min-width:100px}.unified-topbar .top-actions{flex:1;justify-content:flex-end;gap:8px;min-width:0}
.unified-topbar .search{flex:1 1 190px;max-width:320px;min-width:150px}.unified-topbar .search input{width:100%;min-width:0;}
.unified-topbar .secondary,.unified-topbar .primary{font-size:12px;padding:9px 12px;min-height:38px;white-space:nowrap;flex:0 0 auto;box-shadow:none;}
.unified-topbar .icon-button{width:32px;height:36px;flex:0 0 32px;}
.unified-topbar .owner-badge{font:9px/1.4 "Segoe UI",system-ui;letter-spacing:1px;white-space:nowrap;}
.sidebar .nav-group{padding-bottom:9px;gap:2px;}.sidebar .nav-row{min-height:37px;padding:8px 12px;font-size:12px;}
.side-utility-links{display:flex;gap:6px;flex-wrap:wrap;padding:0 6px 16px;}.side-utility-links .recent-link{font-size:10px;padding:6px;gap:5px;min-height:28px;}.side-utility-links .icon{width:12px;height:12px}
.desk-tools{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:1px;border:1px solid var(--line-soft);border-radius:12px;margin-top:18px;overflow:hidden;background:var(--line-soft);}
.desk-tool{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px;background:var(--panel);min-height:76px;padding:12px 6px;font-size:11px;line-height:1.4;text-align:center;color:var(--muted);}
.desk-tool svg{color:var(--accent)}.desk-tool:hover{background:var(--raised);color:var(--text)}.desk-tool:focus-visible{outline-offset:-3px}
.suite-warning{padding:13px;border:1px solid var(--amber);font-size:12px;color:var(--text);margin-bottom:12px;}
.tools-heading{padding:24px 0 20px}.tools-heading h1{font:500 clamp(28px,3vw,44px)/1.1 var(--world-font);letter-spacing:-.8px;}
.tools-heading p{font-size:13px;color:var(--muted);margin-top:13px;line-height:1.7}
.tools-spotlight{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:30px;}.tools-spotlight button{font-size:12px;}
.tools-group{margin:25px 0;}.tools-group h2{font:600 10px/1.6 "Segoe UI",system-ui;letter-spacing:1.8px;color:var(--muted);margin-bottom:12px;}
.tools-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.tool-tile{border:1px solid var(--line);border-radius:var(--world-radius);background:var(--panel);color:var(--text);padding:22px 18px;display:flex;gap:14px;align-items:flex-start;min-width:0;}
.tool-tile>span:nth-child(2){flex:1;min-width:0}.tool-tile strong{font-size:14px;font-weight:600;line-height:1.5;display:block;}
.tool-tile small{display:block;font-size:11px;line-height:1.75;margin-top:7px;color:var(--muted);overflow-wrap:anywhere}
.tool-symbol{display:grid;place-items:center;width:36px;height:36px;flex:0 0 36px;background:var(--accent-soft);color:var(--accent);border-radius:10px;}
.tool-tile>svg{margin-top:12px;width:13px;color:var(--quiet)}.tool-tile:hover{border-color:var(--accent);background:var(--raised);}.tool-tile:disabled{opacity:.45;}
.tools-footnote{font-size:12px;line-height:1.8;color:var(--muted);padding:20px 0 8px;border-top:1px solid var(--line-soft)}
@media(max-width:1240px){.unified-topbar .topbar-left{display:none}.unified-topbar .top-actions{justify-content:flex-start}.unified-topbar .search{max-width:none;}.tools-grid{grid-template-columns:repeat(2,minmax(0,1fr));}}
@media(max-width:950px){.unified-topbar{padding:12px 20px}.unified-topbar .top-actions{flex-wrap:wrap}.unified-topbar .search{flex-basis:100%;height:36px}.unified-topbar .refresh-library{display:none}.desk-tools{grid-template-columns:repeat(3,minmax(0,1fr));}.desk-tool{min-height:66px}.suite-plan-list{grid-template-columns:1fr}.tools-grid{grid-template-columns:1fr}.tool-tile{padding:17px}.tools-spotlight .secondary{font-size:11px}}
@media(max-width:860px){.unified-topbar .topbar-left{display:flex;}.unified-topbar .owner-badge{display:none}.unified-topbar .top-actions{flex-basis:calc(100% - 70px)}.unified-topbar .search{flex-basis:100%}.unified-topbar .top-actions .primary,.unified-topbar .top-actions .secondary{padding:8px;font-size:11px;}}
@media(max-width:480px){.unified-topbar{padding:10px 14px}.unified-topbar .top-actions{gap:5px}.unified-topbar .icon-button{width:26px;flex-basis:26px}.unified-topbar .top-actions .secondary .icon{display:none}.desk-tool{font-size:10px}.tools-spotlight{display:grid;grid-template-columns:1fr 1fr}.tools-heading h1{font-size:28px}.tools-heading{padding-top:12px}}
:host([data-motion="off"]) *, :host([data-motion="off"]) *::before, :host([data-motion="off"]) *::after{transition:none!important;animation:none!important;scroll-behavior:auto!important;}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important;}}

/* RC2 audit: readable identity, visible sorting, unambiguous selected worlds. */
.unified-topbar .owner-badge{font:500 11px/1.5 "Segoe UI",system-ui,sans-serif;letter-spacing:0;text-transform:none;min-height:32px;}
.brand small{font-size:10px;line-height:1.6;letter-spacing:.25px;text-transform:none;}
.brand strong{letter-spacing:-1.1px;}
.world-window .world-window-label small{font-size:10px;letter-spacing:1px;}
.world-window .world-window-label strong{overflow-wrap:anywhere;}
.theme-tile .mini-screen::before{content:"";position:absolute;inset:20% 0 0;background:linear-gradient(transparent,rgba(5,13,17,.86));pointer-events:none;}
.theme-tile .mini-screen::after{z-index:1;color:#fff;}
.theme-check{display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;color:var(--accent-strong);}
.theme-check[hidden]{display:none;}
.library-controls.board-controls{display:flex;justify-content:flex-end;}
.board-controls>.tabs,.board-controls .view-switch{display:none;}
.board-controls::before{content:"Lectures stay in their folders";font-size:11px;color:var(--muted);margin-right:auto;}
.recent-order{font-size:11px;color:var(--muted);padding:6px 2px;}
.library-controls select{max-width:220px;}
@media(max-width:620px){.library-controls.board-controls{display:flex;gap:10px;flex-wrap:wrap}.board-controls::before{flex:1;min-width:130px}.library-controls select{font-size:11px;max-width:185px}}
/* Search and sorting remain available in compact windows; they are not optional decoration. */
.unified-topbar .search{display:flex;}
@media(max-width:365px){.view-tools select{display:block;max-width:170px}.view-tools{gap:8px}.library-controls{flex-wrap:wrap}.library-controls>.tabs{flex-wrap:wrap}}
@media(max-height:620px){.sidebar{overflow-y:auto;overscroll-behavior:contain}.sidebar .side-scroll{flex:0 0 auto;max-height:220px;min-height:130px}.sidebar .brand-row{padding-bottom:14px}}
/* Keep compact navigation in two rows instead of isolating the menu above search. */
@media(max-width:820px){.unified-topbar .topbar-left{min-width:0;flex:0 0 30px;align-self:flex-start;padding-top:1px}.unified-topbar .top-actions{flex:1 1 calc(100% - 52px);width:auto;min-width:0}.unified-topbar .mobile-button{width:30px;flex-basis:30px;justify-content:center}}

