/* Workshop · finished editorial interface. Isolated to this web document. */
html.workshop-host,html.workshop-host body{margin:0;padding:0;background:#141b1b;overflow:hidden}
#workshop{--bg:#141b1b;--sidebar:#111817;--panel:#1b2422;--raised:#23302b;--hover:#2b3a32;--paper:#f3ecdc;--ink:#263c30;--fg:#eeeade;--muted:#a3b1a7;--quiet:#81958a;--line:#34413a;--soft-line:#29372f;--accent:#bdcfa5;--on-accent:#213322;--gold:#cfb685;--danger:#f2aba2;--warning:#e4c080;--shadow:0 18px 40px #0003;--page-pad:clamp(20px,3vw,46px);font:14px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;letter-spacing:-.12px;color:var(--fg);background:var(--bg);height:100vh;text-align:left;-webkit-font-smoothing:antialiased;color-scheme:dark}
#workshop[data-theme="paper"]{--bg:#f3f0e7;--sidebar:#e9e6da;--panel:#fcfaf4;--raised:#e7eddf;--hover:#dce5d2;--fg:#26362c;--muted:#596e5c;--quiet:#687a6d;--line:#cdd3c3;--soft-line:#dce0d2;--accent:#466249;--on-accent:#fffef5;--gold:#816739;--danger:#a7433b;--warning:#916428;--shadow:0 18px 40px #344a3511;color-scheme:light}
#workshop[data-theme="forest"]{--bg:#10201c;--sidebar:#0d1c18;--panel:#182d24;--raised:#233d2b;--hover:#2a4732;--fg:#edf1df;--muted:#afc0a6;--quiet:#8ea388;--line:#36503a;--soft-line:#2b4230;--accent:#cfda99;--on-accent:#233221;--gold:#d8bc72}
#workshop[data-theme="atelier"][data-dark="false"]{--bg:#f3f1eb;--sidebar:#eae7de;--panel:#fffdf8;--raised:#e9eddf;--hover:#dee6d6;--fg:#2b382e;--muted:#617363;--quiet:#6d7c6d;--line:#cfd5c7;--soft-line:#e1e3d8;--accent:#506e52;--on-accent:#fffdf8;--gold:#8f744a;--danger:#a94b43;--warning:#987238;--shadow:0 18px 40px #344a3511;color-scheme:light}
#workshop *,#workshop *::before,#workshop *::after{box-sizing:border-box}#workshop *{scrollbar-width:thin;scrollbar-color:var(--line) transparent}
#workshop button,#workshop input,#workshop select,#workshop textarea{font:inherit;color:inherit}#workshop button{appearance:none;background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:9px 13px;cursor:pointer;line-height:1.3;display:inline-flex;align-items:center;justify-content:center;gap:8px;transition:background .17s,border-color .17s,transform .17s;box-shadow:none;white-space:normal;min-height:36px}#workshop button:hover:not(:disabled){border-color:var(--accent);background:var(--raised)}#workshop button:active:not(:disabled){transform:translateY(1px)}#workshop button:disabled{opacity:.5;cursor:default}#workshop button:focus-visible,#workshop a:focus-visible,#workshop summary:focus-visible,#workshop [tabindex="0"]:focus-visible{outline:2px solid var(--accent);outline-offset:3px}#workshop input:focus,#workshop textarea:focus,#workshop select:focus{outline:2px solid var(--accent);outline-offset:1px}
#workshop input:not([type="checkbox"]):not([type="range"]),#workshop select,#workshop textarea{width:100%;border:1px solid var(--line);border-radius:9px;background:var(--bg);padding:10px 12px;line-height:1.5;min-width:0}#workshop textarea{resize:vertical;min-height:90px}#workshop input::placeholder,#workshop textarea::placeholder{color:var(--quiet);opacity:1}#workshop input[type="checkbox"]{width:17px;height:17px;accent-color:var(--accent);flex-shrink:0}#workshop input[type="range"]{accent-color:var(--accent);width:100%}#workshop select{cursor:pointer}#workshop .icon{width:20px;height:20px;vertical-align:middle;flex-shrink:0}#workshop .icon-btn{width:36px;padding:8px;flex-shrink:0}#workshop .primary{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}#workshop .primary:hover:not(:disabled){background:var(--accent);filter:brightness(1.06);color:var(--on-accent)}#workshop .quiet{background:transparent;border-color:transparent;color:var(--muted)}#workshop .danger{color:var(--danger)}#workshop .small{font-size:12px;padding:7px 10px;min-height:32px}#workshop .text-btn{background:transparent;border:0;padding:2px 0;min-height:28px;color:var(--accent);font-size:12px}#workshop .text-btn:hover{background:transparent!important;text-decoration:underline}#workshop .full{width:100%}#workshop .row{display:flex;align-items:center;gap:10px;min-width:0}#workshop .wrap{flex-wrap:wrap}#workshop .between{justify-content:space-between}#workshop .right{margin-left:auto}#workshop .stack{display:flex;flex-direction:column;gap:14px}#workshop .muted{color:var(--muted)}#workshop .fine{font-size:12px;color:var(--muted);line-height:1.7}#workshop .micro{font-size:10px;color:var(--quiet);letter-spacing:.3px}#workshop .eyebrow{font-size:10px;letter-spacing:2.4px;text-transform:uppercase;color:var(--gold);font-weight:600}#workshop h1,#workshop h2,#workshop h3,#workshop p{margin:0}#workshop h1{font:normal clamp(30px,3vw,43px)/1.15 Georgia,"Times New Roman",serif;letter-spacing:-1.1px}#workshop h2{font:normal 25px/1.3 Georgia,"Times New Roman",serif;letter-spacing:-.6px}#workshop h3{font-size:15px;line-height:1.4;font-weight:600}#workshop .serif{font-family:Georgia,"Times New Roman",serif}#workshop .pill{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);background:var(--raised);border-radius:6px;padding:3px 7px;font-size:10px;line-height:1.5;color:var(--muted);white-space:nowrap}#workshop .pill.accent{color:var(--accent)}#workshop .pill.warn{color:var(--warning)}#workshop .dot{width:5px;height:5px;border-radius:50%;background:currentColor;display:inline-block}#workshop label.field{display:flex;flex-direction:column;gap:7px;font-size:12px;font-weight:550}#workshop label.field small{font-weight:400;color:var(--muted);line-height:1.65;font-size:11px}#workshop .form-grid{display:grid;grid-template-columns:1fr 1fr;gap:17px}#workshop .check{display:flex;align-items:flex-start;gap:10px;font-size:12px;font-weight:400;cursor:pointer;line-height:1.7}#workshop .check input{margin:2px 0 0}#workshop .check small{display:block;color:var(--muted);font-size:11px}#workshop .notice{padding:12px 14px;border:1px solid var(--line);border-left:3px solid var(--gold);border-radius:3px 9px 9px 3px;color:var(--muted);background:var(--panel);font-size:12px;line-height:1.7}#workshop .notice.error{border-left-color:var(--danger)}#workshop .notice.success{border-left-color:var(--accent)}#workshop .pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.75}#workshop code{background:var(--raised);font:11px/1.6 ui-monospace,Consolas,monospace;padding:2px 5px;border-radius:4px;overflow-wrap:anywhere}#workshop hr{border:0;border-top:1px solid var(--line);margin:19px 0}
/* Shell */
