async function attachmentDialog(payload){if(!S.project){closeModal();projectDialog();throw new Error('Create a project, then choose the attachment again.');}if(!S.draft)createDraftObject('image');const audio=payload.image?.startsWith('data:audio');showModal(audio?'A voice for this card.':'Use this image deliberately.','The original media is not replaced or deleted.',`${audio?`<audio controls src="${E(payload.image)}" style="width:100%"></audio>`:`<img class="preview-media" src="${E(payload.image)}" alt="Selected media">`}<div class="form-grid" style="margin-top:18px"><label class="field">Attach to<select id="ws-attachment-side">${option('front','Question side','front')}${option('back','Answer side','front')}</select></label><label class="field">Description / accessible label<input id="ws-attachment-alt" maxlength="200"></label></div>${!audio?'<p class="fine" style="margin-top:13px">For masks, use Mask image here after attaching. Workshop does not flatten or rewrite existing mask formats.</p>':''}`,B('close-modal','Cancel','','small')+B('confirm-modal','Attach to draft','check','primary small'),async()=>{S.draft.media.push({blob:payload.blob,side:$('#ws-attachment-side').value,alt:$('#ws-attachment-alt').value});if(payload.source&&S.source)Object.assign(S.draft,{source_id:S.source.source.id,version_id:S.source.version.id,page:S.page,quote:S.selection});markDirty();closeModal();S.view='studio';render();await saveDraft();toast('Media attached to the local draft.');});}
